-- GENERATED by `wfi generate` from data/quest/quest-0001.jsonl. Do not edit: `wfi validate` regenerates and diffs it.
local _, WFI = ...
WFI.Data.add("quest", {
  [1000] = { "La nuova frontiera", nil, nil, nil, nil, 0x980efd04, nil, nil, nil, nil, ".mmmm" },
  [1001] = { nil, "Raccogli 3 Thresher Eyes dai Darkshore Threshers nel mare profondo vicino al Buzzbox 411.", "Una vocina gracchia dal fondo della macchina.\n\n\"Qui Wizbang! Il prossimo Buzzbox è a nord di Auberdine, sulla spiaggia\n\nAllora, quel Buzzbox è il numero 411 e per ripararlo servono 3 Thresher Eyes. Sono appena al largo della costa! I darkshore thresher... *Hic*... Scusa...\n\nCome l'altra volta, quando dai al Buzzbox la roba, sputerà fuori la tua ricompensa. *Hic*... Cosa? No, sto benissimo!\"", "Lo sportello della macchina è aperto e sembra attendere con impazienza che vi vengano messi 3 Thresher Eyes.", "Il Buzzbox si rianima poco dopo che hai messo dentro i Thresher Eyes. C'è un attimo di statica prima che tu senta una vocina familiare.\n\n\"Il vino di crawler è il migliore...\" *hic*\n\n\"Cosa? Oh, l'hai già riparato? Accidenti, shei proprio veloce. Allora, vuoi ripararne un altro?\"\n\nTi sembra di sentire un liquido versato in una tazza, seguito da rumorose sorsate.", nil, 0xe7f4d482, 0x03c10b82, 0x32d3a2c9, 0x37ad4bdf, "m...." },
  [1002] = { nil, "Raccogli 6 Moonstalker Fangs e mettili nel Buzzbox 323.", "Il Buzzbox emette una scarica di statica e senti Wizbang cominciare a parlare.\n\n\"Il proshimo Buzzbox è il numero 323. È a nord di Auberdine ma... dov'è la birra? Eh? Oh, è sulla shtrada, quindi non dovresti avere problemi a trovarlo vicino al ponte.\"\n\nWizbang borbotta qualcosa di incomprensibile, poi senti un rumoroso sorso.\n\n\"Quesht'altro vuole Moonstalker Fangs... 6.\"", "Anche se non hai ancora messo dentro i 6 Moonstalker Fangs, ti sembra di sentire provenire dall'interno rumori di statica e borbottii incoerenti di uno gnomo. Che qualcun altro abbia già riparato la macchina?", "Il Buzzbox entra improvvisamente in azione e dall'interno senti distintamente il rumore di denti ridotti in polvere.\n\n\"Allora, ce l'hai fatta! Shono notizie ecshellenti... Allora... Perché non vai avanti? Oh! A meno che tu non voglia un altro lavoro!\"", nil, 0x81dea735, 0xb07e5e5e, 0x32946a73, 0xcd12f60d, "m...." },
  [1003] = { nil, "Raccogli 4 Grizzled Scalps dai Grizzled Thistle Bears a sud di Auberdine e mettili nel Buzzbox 525.", "Tra i gorgoglii e gli sgocciolii che escono dalla macchina, senti la voce tremolante di Wizbang.\n\n\"Il proshimo è molto a shud lungo la shtrada. Non dovrebbe esshere difficile da trovare... proprio di lato... vishino a uno shteccato. Mi pare di averlo nashcosto nei cespugli... Cesh... pugli. Eheh... Shì, il Buzzbox 525 prende le Grizzled Scalps da quei grizzled thistle bear. Accidenti che shcioglilingua. Grizzshled... Eheh...\"\n\nSenti altri sorsi mentre la macchina si spegne. Poi, all'improvviso, torna in vita.\n\n\"4!\"", "Senti cantare il Buzzbox 525.\n\n\"Il vino di crawler è dolshe, la birra di thresher è fina, e il liquore di moonstalker è shuperbo. Ma niente è più caro di una birra di thistle bear, e presto ne avrò un bel barile!\"\n\nLo sportello è aperto e attende i 4 grizzled scalps, mentre senti la canzone ripetersi all'infinito.", "\"Allora hai messho dentro gli scalpi? È fantashtico... Cosha? Beh, shì, immagino tu abbia capito che posso parlarti anche shenza i materiali nella macchina. Ma dicevo la verità quando ho detto che erano rotti!\n\nVedi, oltre a esshere strumenti di comunicazzione, i Buzzbox produshono e dishtillano anche liquori pregiati. Shcusa l'inganno, ma gli elfi della notte non apprezzano il mio commercio di liquori nelle loro città. Ho messo qualcosa di shpeciale in queshta scatola per mostrarti la mia gratitudine per i tuoi shforzi. Goditelo!\"", nil, 0x456f18b8, 0x7c095433, 0x36f0523a, 0x8072af47, "m...." },
  [1004] = { "La nuova frontiera", nil, nil, nil, nil, 0x980efd04, nil, nil, nil, nil, ".mmmm" },
  [1007] = { "L'Ancient Statuette", "Porta l'Ancient Statuette a Talen, nel suo accampamento vicino allo Zoram Strand.", "Vorrei affidarti un compito, {name}.\n\nEro sulla mia piccola imbarcazione e scivolavo sopra le rovine sommerse di Zoram quando i naga mi hanno attaccato, emergendo dall'acqua e dilaniandomi con gli artigli! Sono fuggito, portando con me le provviste che potevo per allestire questo misero accampamento.\n\nMa quando ho raggiunto la riva e sono scappato... ho perso il mio bene più prezioso.\n\nTi prego, {name}, trova il luogo dell'imboscata, lungo la costa a nord, e cerca un'antica statuetta. È il motivo per cui ho sfidato i pericoli dello Zoram Strand.", "Hai trovato la statuetta, {name}?", "L'hai trovata! Grazie, {name}!\n\nL'antica città di Zoram custodisce molti segreti, e questa statuetta potrebbe essere la chiave di molti di essi.", 0x4f6fc8bc, 0x8d5ca3e4, 0xc4983d64, 0x4a9921c4, 0xad8649d6, "....." },
  [1008] = { "Lo Zoram Strand", "Porta 20 Wrathtail Heads a Shindrell Swiftfire, ad Astranaar.", "Sulla nostra costa nord-occidentale, nota come Zoram Strand, si annida il male.\n\nÈ il luogo di riposo della città maledetta di Zoram, distrutta durante la Sundering e sprofondata sotto i mari. È perduta per gli elfi della notte da ere. Perduta e quasi dimenticata.\n\nOra i naga sono tornati, e non sappiamo per quale motivo. Ma il motivo conta poco: dobbiamo uccidere questi demoni e ricacciarli negli abissi!\n\nTorna da me quando la tua missione sarà compiuta.", "Non possiamo permettere ai naga di invadere le nostre coste, {name}. È fondamentale che tu vada allo Zoram Strand e porti a termine la tua missione.", "Davvero ben fatto, {name}. Le tue azioni contro i naga allo Zoram Strand sono encomiabili.\n\nSo che la tua impresa non è stata facile, perché la forza e l'astuzia dei naga sono ben note agli elfi della notte. Lo sappiamo perché condividiamo con loro una storia.\n\nÈ una storia che non desidero si ripeta.", 0x9cbacfd8, 0x9d25563d, 0x187db273, 0x72b741c0, 0xd6ba7f97, "....." },
  [1009] = { nil, "Porta il Ring of Zoram a Talen, vicino allo Zoram Strand.", "Temo che i segreti dell'antica statuetta resteranno nascosti per sempre, a meno che tu non trovi la chiave della sua antica serratura.\n\nQuella chiave è un anello, il Ring of Zoram. Apparteneva ai sovrani di questa città prima che le onde della Sundering la sommergessero.\n\nPer anni l'anello è rimasto perduto, ma di recente i naga l'hanno trovato.\n\nLa loro capa, Ruuzel, dimora su un'isola al margine settentrionale di Zoram. Ti prego, {name}, recupera l'anello per me!", "Si dice che il Ring of Zoram sia la chiave di qualsiasi serratura della città. Ce l'hai, {name}?", "Hai trovato l'anello! Grazie, {name}. Accetta questo come pagamento, e sappi che le tue imprese di oggi resteranno per sempre nella mia memoria.", nil, 0x9ce8fe4c, 0x90dfae10, 0xfa173a78, 0x281d1a0e, "m...." },
  [1010] = { nil, "Porta 5 Bathran's Hair a Orendil Broadleaf, ad Ashenvale.", "C'è una pianta che un tempo cresceva tra le antiche rovine di Bathran's Haunt, a nord. Si chiamava Bathran's Hair ed era nota per curare i mali dello spirito.\n\nNel villaggio c'è un bambino malato, e credo che non si tratti solo di una malattia fisica. Andrai a Bathran's Haunt a cercare il Bathran's Hair? Potrebbe servirmi per curare il bambino come si deve.\n\nBathran's Haunt si trova a nord del Maestra's Post, appena a sud del confine con Darkshore.", "Hai raccolto il Bathran's Hair, {name}? La salute del bambino peggiora di ora in ora...", "Ah, hai l'erba! Ora preparerò una cura per il bambino, e pregherò che il mio intruglio funzioni.\n\nE... ci sono i Forsaken a Bathran's Haunt? È molto preoccupante sentirlo. Davvero molto preoccupante...", nil, 0xd56778b9, 0xaa6b3524, 0x340001ab, 0xbadaf9b1, "m...." },
  [1011] = { "Le malattie dei Forsaken", "Porta una Bottle of Disease a Kayneth Stillwind, a Forest Song.", "I Forsaken, il braccio non morto dell'Horde, sono penetrati ad Ashenvale, annidandosi nelle nostre rovine e nei nostri tumuli. Crediamo che il loro obiettivo sia diffondere malattie nelle terre degli elfi della notte. Dobbiamo averne conferma!\n\nI Forsaken hanno un accampamento a sud di qui, vicino al Dor'Danil Barrow Den, dove creano veleni e malattie e li mettono in bottiglie. Fatti strada combattendo in quell'accampamento e ruba una bottiglia di malattia. Torna con una di quelle bottiglie. La analizzerò e ne scoprirò lo scopo.", "Hai trovato l'accampamento, {name}? Hai una bottiglia di malattia?", "Molto bene, {name}. Ora... analizzando il contenuto di questa bottiglia, gli obiettivi dei Forsaken verranno svelati!", 0x56f1d203, 0x2dc3785e, 0xb7d7e188, 0x4bef8879, 0x706dafea, "....." },
  [1012] = { "Druidi impazziti", "Uccidi i druidi Taneel Darkwood, Uthil Mooncall e Mavoris Cloudsbreak, poi torna da Kayneth Stillwind, a Forest Song.", "Mentre lottavo contro i veleni dei Forsaken, ho avuto una visione. Ho visto i druidi del Dor'danil Barrow Den avvelenati... assassinati dai non morti! Ora sono spettri erranti, separati dai loro corpi e impazziti.\n\nPerché gli spiriti dei druidi possano un giorno trovare pace, devi entrare nel Dor'danil Barrow Den e distruggere coloro che un tempo erano i suoi grandi capi: Taneel Darkwood, Uthil Mooncall e Mavoris Cloudsbreak.\n\nFallo, poi torna da me.", "L'angoscia dei druidi di Dor'danil tormenta ancora i miei sogni, {name}. Devi distruggere i loro capi!", "Ho sentito l'angoscia dei Dor'danil Barrows attenuarsi e ho capito che avevi portato a termine il tuo compito.\n\nHai svolto un lavoro cupo, {name}, perché gli spiriti che hai distrutto erano solo vittime della malvagità dei Forsaken. Ma con la loro distruzione, speriamo che gli altri spiriti impazziti trovino pace.", 0x64537763, 0xe520e963, 0x73bdfd08, 0x1fc933f7, 0x6109c515, "....." },
  [1015] = { "La nuova frontiera", "Parla con Arch Druid Fandral Staghelm nel Cenarion Enclave di Darnassus della chiamata del Cenarion Circle a esplorare le frontiere di Kalimdor.", "Attenzione, eroi!\n\nIl Cenarion Circle cerca persone abili che lo aiutino a esplorare le vaste nuove frontiere di Kalimdor! Una terra desolata e proibita, piena di pericoli inimmaginabili, si trova molto a ovest di Tanaris e di Gadgetzan, e il Circle ha bisogno di rappresentanti volenterosi e onorevoli che agiscano al suo posto.\n\nTutti gli interessati dovrebbero chiedere udienza al Cenarion Circle. Parlate con l'arcidruido di Darnassus, Fandral Staghelm, per maggiori informazioni!", nil, "Cosa ti fa pensare che io voglia essere importunato da gente come te, {class}? Aspetta, lascia che interrompa i doveri importanti di cui mi occupo ogni giorno per aiutarti a trovare un aggeggio da qualche parte. Ma certo, il benessere di Darnassus, anzi, di tutta Teldrassil, deve venire dopo l'acquisto di un ninnolo per la tua collezione.\n\nQuegli sciocchi di Moonglade mi fanno perdere tempo con la loro richiesta di aiuto, e ora devo sopportare anche questo?", 0x980efd04, 0x419bdcfb, 0x5f025126, nil, 0xc02ec71d, "...m." },
  [1016] = { "Bracciali elementali", "Raccogli 5 Intact Elemental Bracers e usa su di essi il Divining Scroll. Poi porta il Divined Scroll alla Sentinel Velene Starstrike, al Silverwind Refuge.", "Prendi questa pergamena di divinazione: può rivelare il creatore di questi elementali. Ma ti servirà qualcosa da loro da usare come reagente per concentrare la magia della pergamena; i loro bracciali dovrebbero andar bene.\n\nBasteranno alcuni bracciali intatti di quelle creature. Gli altri bracciali saranno inutili per i nostri scopi, ma potrebbero valere qualcosa per un mercante se vuoi venderli. Una volta avuti i bracciali intatti, prova a usare la pergamena. Torna da me con i risultati e procederemo da lì.", "Dato che uccidendo gli elementali ne distruggi i bracciali, sarà probabilmente difficile trovare proprio quelli che contengono le informazioni di cui la pergamena di divinazione ha bisogno. Puoi scambiare bracciali con altri per ottenere quelli che ti servono, oppure forse hai già la pergamena divinata?", "Ben fatto, {name}: questo dovrebbe darci le informazioni necessarie per scoprire il colpevole. Che ne diresti di eliminare il mago che riempie le nostre pozze di elementali corrotti? La corruzione di Ashenvale e oltre mi dà già il voltastomaco da sola; che uno stregone cerchi attivamente di peggiorarla mi disgusta oltre ogni limite. Gliela faremo pagare.", 0xb698effb, 0xdea3d96f, 0x737c6b17, 0x90279ef1, 0x7f18db5a, "....." },
  [1017] = { "Il mago evocatore", "Uccidi Sarilus Foulborne e porta la sua testa alla Sentinel Velene Starstrike, al Silverwind Refuge.", "C'è un solo mago non morto nelle Barrens capace di profanare così tanti elementali dell'acqua. Ed è anche l'unico abbastanza sciocco da provarci. Sarilus Foulborne è probabilmente seduto in cima al Dreadmist Peak a ridere di me.\n\n{name}, devi entrare in territorio nemico e distruggere questo farabutto. Ne ho abbastanza della sua idiozia e dobbiamo mostrargli cosa succede a chi infastidisce le Sentinels.\n\nDistruggilo e portami la sua testa. Ma <attento/attenta>: l'Horde potrebbe tenerti d'occhio.", "È fatta? Sarilus Foulborne è morto?", "Ora posso vedere quel sorriso ripugnante cancellato per sempre dalla sua faccia. Hai fatto molto bene, {name}. Prendi questa, la Light of Elune: bevila quando tutto sembra perduto e la morte è vicina. Potrebbe salvarti, se la dea vorrà.", 0xd88bf407, 0x0a5ea9a8, 0xb383c3fe, 0xd734a9d3, 0x762bf18f, "....." },
  [1018] = { "La nuova frontiera", nil, nil, nil, nil, 0x980efd04, nil, nil, nil, nil, ".mmmm" },
  [1019] = { "La nuova frontiera", "Parla con Arch Druid Fandral Staghelm nel Cenarion Enclave di Darnassus della chiamata del Cenarion Circle a esplorare le frontiere di Kalimdor.", "Attenzione, eroi!\n\nIl Cenarion Circle cerca persone abili che lo aiutino a esplorare le vaste nuove frontiere di Kalimdor! Una terra desolata e proibita, piena di pericoli inimmaginabili, si trova molto a ovest di Tanaris e di Gadgetzan, e il Circle ha bisogno di rappresentanti volenterosi e onorevoli che agiscano al suo posto.\n\nTutti gli interessati dovrebbero chiedere udienza al Cenarion Circle. Parlate con l'arcidruido di Darnassus, Fandral Staghelm, per maggiori informazioni!", nil, "Cosa ti fa pensare che io voglia essere importunato da gente come te, {class}? Aspetta, lascia che interrompa i doveri importanti di cui mi occupo ogni giorno per aiutarti a trovare un aggeggio da qualche parte. Ma certo, il benessere di Darnassus, anzi, di tutta Teldrassil, deve venire dopo l'acquisto di un ninnolo per la tua collezione.\n\nQuegli sciocchi di Moonglade mi fanno perdere tempo con la loro richiesta di aiuto, e ora devo sopportare anche questo?", 0x980efd04, 0x419bdcfb, 0x5f025126, nil, 0xc02ec71d, "...m." },
  [1020] = { nil, "Porta l'Orendil's Cure a Pelturas Whitemoon, ad Astranaar.", "{name}, ho preparato una cura che credo aiuterà il bambino malato. Portala ad Astranaar e consegnala al genitore del bambino, Pelturas Whitemoon.\n\nPer raggiungere Astranaar, segui la strada verso sud, poi verso est.", "Devo scusarmi, non ho tempo per parlare. La mia bambina, Relara, è gravemente malata!", "Viene da Orendil?\n\nLa sua abilità con le erbe e la guarigione è grande. Questa cura mi dà speranza, quando prima ne avevo poca...", nil, 0xb594b387, 0x15801dd7, 0xb4a8bb23, 0x6dfa2147, "m...." },
  [1021] = { "Satiri malvagi! Driadi in pericolo!", "Trova Anilia a Xavian.", "Ascolta, non so chi tu sia, ma ho bisogno del tuo aiuto. Le mie sorelle sono andate a riprendere il Branch of Cenarius dai satiri. Hanno detto che sarebbero tornate presto, ma sono passati due giorni interi!\n\n{name}, devi trovarle! Cercavano le rovine di un tempio degli elfi della notte a Xavian, a nord-est. Non so cosa pensare. Cerca Anilia: guidava lei la ricerca.", nil, "A giudicare dalla ferita spalancata sul fianco, Anilia è in punto di morte.", 0xd88516a4, 0x901c0e74, 0x32056a49, nil, 0xe36895ac, "...m." },
  [1022] = { "La Howling Vale", "Va' alla Howling Vale e studia il Tome of Mel'Thandris, poi torna dalla Sentinel Melyria Frostshadow, allo Shrine of Aessina.", "Anche se abbiamo impiegato molte risorse e molti sforzi per scacciare i demoni rimasti nella Felwood a nord, i nostri successi sono stati pochi. Siamo riusciti a tenere gran parte della presenza demoniaca lontano da Ashenvale.\n\nA nord, vicino al confine con la Felwood, il santuario in rovina di Mel'Thandris è stato occupato da misteriosi uomini lupo. I loro richiami agghiaccianti hanno fatto sì che la zona sia conosciuta come la Howling Vale. Il Tome of Mel'Thandris custodito nel santuario potrebbe far luce sul perché questi uomini lupo siano arrivati.", "Il tomo del santuario è un oggetto misterioso. Non è un libro nel senso tradizionale. Le pagine del tomo furono benedette dalla stessa Mel'Thandris, e vi sono registrati eventi importanti.\n\nÈ difficile da spiegare. Se andrai al santuario, capirai.", "Il Tome of Mel'Thandris funziona in modi strani. Gli eventi che registra, gli eventi che mostra... Nessuno capisce davvero perché fa ciò che fa.\n\nAd ogni modo, è chiaro che ciò che la sacerdotessa Starsong ha ricevuto, questa Scythe of Elune, merita ulteriori indagini.", 0x4a2cd655, 0xda6b6938, 0x9b613692, 0x9ace9f35, 0xa2144a21, "....." },
  [1023] = { "La purificazione di Raene", "Trova il Glowing Gem e torna da Raene Wolfrunner, ad Astranaar, con il Teronis' Journal.", "Frugando tra gli effetti di Teronis, trovi un diario ancora in buone condizioni.\n\nPrendi il diario e lasci il cadavere di Teronis così com'è.\n\nNon resta che trovare la gemma che Teronis cercava. Raene ha detto che si trova in zona. Forse ce l'hanno i murloc...", "Ah, <bentornato/bentornata>, {name}.", "È terribile, {name}. Teronis è morto?!\n\nVerrà il tempo del lutto, ma per ora dobbiamo concentrare i nostri sforzi. Manderò alcune Sentinels a recuperare il corpo di Teronis il prima possibile.\n\nHai il diario di Teronis e la gemma che cercava. Ti senti in grado di portare a termine il suo compito? Riposerei molto meglio sapendo che la sua morte non è stata vana.", 0x30e3be54, 0x7f853c3d, 0xba0a18d8, 0x6c186150, 0x213bef75, "....." },
  [1024] = { "La purificazione di Raene", "Trova Shael'dryn al pozzo lunare a nord-est.", "Dovrai fare tu le ricerche, ma dagli appunti di Teronis sembra che la tua prossima mossa sia trovare gli altri pezzi della verga creata da Dartol. Comincerei dirigendomi al pozzo lunare a est dell'Iris Lake. Quando sei <pronto/pronta>, segui la strada e gira a nord quando raggiungi una piccola area di sosta sulla sinistra.\n\nLì c'è una driade di nome Shael'dryn, più adatta a guidarti. Cercala.\n\nTieni con te la gemma: a Shael'dryn servirà se dovrà aiutarti a ricostruire la verga.", "Salve. Come stai?", "Oh, ti ha mandato Raene? Dev'essere davvero una cosa seria. In cosa posso aiutarti?", 0x30e3be54, 0x870564ea, 0x74ecbe19, 0x8c397c59, 0xf0f35728, "....." },
  [1025] = { "Una difesa aggressiva", "Uccidi 1 Den Watcher, 2 Ursa, 10 Totemic e 12 Warrior della tribù Foulweald, poi torna da Raene Wolfrunner, ad Astranaar.", "Prima che tu vada al pozzo lunare, ho un altro compito che aiuterà la gente di Ashenvale, se vuoi mettere alla prova le tue capacità.\n\nLungo la strada verso est, prima del Falfarren River, i furbolg attaccano i viaggiatori. Le loro menti tormentate si nutrono di paura e i loro appetiti si saziano del sangue degli innocenti.\n\nAiuta le Sentinels a proteggere queste terre mostrando a quei mostri la stessa pietà che hanno mostrato alla nostra gente.\n\nCredo che i loro accampamenti siano a sud della strada... fa' attenzione.", "I furbolg non sono sempre stati nostri nemici, {name}. Ma i tempi cambiano, e in questi boschi oscuri non è più tempo di pace.", "Hai fatto bene, {name}. Grazie.", 0xac8970c1, 0x61ad4540, 0xb29beaa2, 0xa6e6b187, 0x53926f7d, "....." },
  [1026] = { "La purificazione di Raene", "Trova la Wooden Key e un pezzo del Dartol's Rod prima di tornare da Shael'dryn al pozzo lunare.", "Vorrei che le tue notizie fossero migliori.\n\nRaene ha ragione, conosco la creazione di Dartol e i treant della zona... almeno, un tempo li conoscevo. Ora sono stati corrotti, la loro natura è stata distorta.\n\nSe il tuo obiettivo è trovare il prossimo pezzo della verga, dovrai trovare la chiave per aprire il forziere che lo contiene.\n\nLa chiave di legno ce l'ha uno dei treant a nord-est di qui, vicino alla Felwood. Una volta presa, cerca una piccola radura a ovest della strada vicino al confine con la Felwood... il forziere dovrebbe essere nascosto da quelle parti.", "Mi addolora tanto che i treant siano stati corrotti. Vorrei poter fare di più per aiutarli.", "Sono lieta di vederti tornare, {name}.", 0x30e3be54, 0x8ec36891, 0xbb4dd335, 0x2a083fa2, 0xee5a6576, "....." },
  [1027] = { "La purificazione di Raene", "Trova l'ultimo pezzo del Dartol's Rod e torna da Shael'dryn al pozzo lunare.", "L'ultimo pezzo della verga fu affidato ai druidi di Dor'danil perché lo custodissero. Non ho idea di dove l'abbiano nascosto. Mi spiace di non poterti aiutare più di così.\n\nPosso solo dirti di seguire la strada che porta verso le Barrens. I druidi si rifugiarono a est di quella strada, ma non ti saranno di grande aiuto: sono stati uccisi di recente... è una cosa a cui preferisco non pensare troppo.\n\nQuando troverai l'ultimo pezzo, portamelo e ti aiuterò a ricostruire la verga.", "Hai trovato l'ultimo pezzo della verga, {name}?", "Hai trovato l'ultimo pezzo? Magnifico per te... e per Raene.\n\nImmagino che dovremo vedere di ripararla, no?", 0x30e3be54, 0x717478b4, 0x52aaaf37, 0xe95940f0, 0x5810af11, "....." },
  [1028] = { "La purificazione di Raene", "Trova il santuario nascosto e incanta di nuovo il Dartol's Rod.", "Ecco la verga completa, {name}. Ricostruirla è stato semplice... la parte difficile sarà trovare il santuario che ha il potere di ricaricarla.\n\nCon un po' di concentrazione e di impegno non dovrebbe essere troppo difficile per qualcuno come te, che ha già compiuto così tanto.\n\nDirigiti a sud-est di qui (i sentieri sono pochissimi, quindi fa' attenzione) e tieni gli occhi rivolti a nord. Il santuario è nascosto tra le montagne che circondano questa radura.\n\nUna volta lì, metti la verga nel santuario... il resto è magia. Eheh.", "Percepisci una forza sottile ma potente nel santuario e negli alberi intorno.\n\nCominci a mettere la verga nel santuario e un leggero ronzio si diffonde intorno a te mentre il santuario comincia a brillare...", "Quando il bagliore si spegne, vedi la verga nuovamente incantata nella vasca del santuario.", 0x30e3be54, 0xb46bc4dc, 0xba1c18cf, 0xbf739d88, 0x772d23ad, "....." },
  [1029] = { "La purificazione di Raene", "Torna da Raene Wolfrunner, ad Astranaar.", "Ti consiglio di trovare Raene e farle sapere che la verga è pronta. Sono sicura che saprà quale sarà la tua prossima mossa.\n\nBuona fortuna, {name}.", nil, "Hai ricostruito la verga che Teronis era partito per trovare? È magnifico sentirlo.\n\nTeronis sarebbe fiero di vedere che la sua missione continua anche dopo la sua tragica scomparsa.", 0x30e3be54, 0x03b8caf8, 0x075c1399, nil, 0x6da04e68, "...m." },
  [1030] = { "La purificazione di Raene", "Trova un furbolg non corrotto e, usando il potere del Dartol's Rod of Transformation, parlagli.", "Ahimè, non sono del tutto sicura di cosa avesse in mente dopo.\n\nSe ciò che diceva sul potere della verga è vero, ti permetterà di assumere tutt'altra forma. Quale forma, non lo so.\n\nForse intendeva usarne i poteri per avvicinarsi ai furbolg contaminati, ma persino le creature non corrotte lo avrebbero massacrato se non fosse stato prudente. Trasformato dalla verga, Dartol avrebbe dovuto parlare con un furbolg al sicuro dagli effetti del Fel Moss.\n\nComincerei a cercare a sud-est del Mystral Lake.", nil, "Sì, sì... sei <uno/una> della mia specie, ma ancora <integro/integra>. Ancora <puro/pura>.\n\nNon so come tu sia <sfuggito/sfuggita> alle atrocità che gli elfi della notte hanno inflitto al nostro popolo, ma sono felice di sapere che non sono più solo.\n\nOra la corruzione scorre nelle vene della nostra gente, giovane, una corruzione portata su di noi dai superbi elfi della notte. Sono loro ad aver fatto questo al nostro popolo... Sono loro che incolpo per essere stato cacciato dalla mia tribù.\n\nDi notte vedo ancora i fuochi da campo ardere nell'oscurità.", 0x30e3be54, 0x9860f324, 0x7bc02b85, nil, 0xcb923d4d, "...m." },
  [1031] = { "Il Branch of Cenarius", "Uccidi Geltharis e riporta il Branch of Cenarius a Illiyana, allo Shrine of Aessina.", "Anilia ti posa le mani sulle spalle e ti attira a sé. Ansimando, indica l'arco a nord, prima che i suoi occhi si chiudano e l'ultimo respiro affannoso lasci il suo corpo. \"L'ha preso lui... Geltharis...\" Senti nel cuore che l'ultimo desiderio di Anilia è vedere il Branch of Cenarius di nuovo nelle mani delle driadi.", "Le hai trovate? Cosa ha detto Anilia? Dov'è?", "Anilia è morta? No... non può essere! Solo ieri correvamo e giocavamo insieme nei boschi.\n\nImmagino che quei giorni siano finiti...", 0x06ca6f6f, 0x9a671e71, 0x0638efcd, 0xb34326a3, 0x2df30514, "....." },
  [1032] = { "A caccia di satiri!", "Porta 16 Satyr Horns a Illiyana, allo Shrine of Aessina.", "Non riesco a credere che Anilia non ci sia più... Giocavamo sempre insieme nelle foreste. Mi sento quasi... triste.\n\nSo una cosa che potrebbe farmi sentire meglio. Ti prego, uccidi i satiri che mi hanno portato via Anilia! Portami le loro corna come prova delle tue azioni e avrai per sempre la mia gratitudine.", "Ti prego, aiutami a vendicare la morte di Anilia.", "Grazie, gentile {race}. Lo spirito di mia sorella è allietato dai tuoi sforzi.", 0x23fc501b, 0x51622fb0, 0x190a00e6, 0x713f462d, 0xd7c8e1b7, "....." },
  [1033] = { nil, "Porta l'Elune's Tear a Pelturas, ad Astranaar.", "Speravo che la cura di Orendil salvasse Relara, ma temo che abbia solo rallentato la malattia che consuma la mia bambina. Dobbiamo trovare una medicina più potente! Per fortuna Orendil mi ha parlato di altri rimedi da provare se il primo avesse fallito.\n\nL'Elune's Tear è un tipo di pietra che si trova in un solo luogo: l'isola dell'Iris Lake, a est di Astranaar. Orendil ha detto che la pietra lava via la corruzione... ti prego, {name}, portami l'Elune's Tear e prega che ponga fine alla malattia della mia bambina!", "{name}, hai trovato l'Iris Lake? Hai la Tear?", "Oh, l'hai trovata! Metterò la lacrima in uno stufato e pregherò che la guarisca.\n\nGrazie! Grazie, {name}!", nil, 0xc2de57c8, 0x0451f462, 0xfd413dac, 0x3c6ec55f, "m...." },
  [1034] = { "Le Ruins of Stardust", "Porta 5 Handfuls of Stardust a Pelturas, ad Astranaar.", "L'Elune's Tear ha lavato via parte della malattia di mia figlia. I suoi incubi sono diminuiti e ringrazio la dea per la sua benedizione. Ma... la febbre la divora ancora.\n\nOrendil mi ha parlato di una polvere brinata che si trova tra le Ruins of Stardust. Forse farà calare la febbre di Relara. Raccogline un po', poi ti prego torna da me.\n\nLe Ruins of Stardust si trovano a sud, {name}. Che Elune acceleri il tuo viaggio.", "Hai già la Stardust, {name}?", "Hai raccolto la polvere! Ne farò un impiastro: dovrebbe far scendere la febbre di Relara.\n\nGrazie ancora, {name}. Senza il tuo aiuto la mia bambina morirebbe di sicuro.", 0xfba883e2, 0xdede75fb, 0x14b3b904, 0x2c3445f3, 0x8980ab64, "....." },
  [1035] = { nil, "Recupera una Fallen Moonstone dallo Shadethicket Oracle, poi portala a Pelturas, ad Astranaar.", "La febbre di Relara è passata, ma è ancora molto debole. Non credo che il tempo da solo le restituirà le forze che ha perso. Credo che servirà il potere di una pietra lunare.\n\nUn tempo raccoglievamo le pietre lunari al Fallen Sky Lake, a sud-est... finché non sono arrivati gli Shadethicket.\n\nIl loro capo, uno Shadethicket Oracle, ha raccolto tutte le pietre lunari cadute e le tiene per sé. Ora devi recuperare una pietra lunare dall'Oracle.\n\nE per farlo, temo che dovrai ucciderlo.", "Hai affrontato lo Shadethicket Oracle, {name}? Se sì, ti prego, dammi la pietra lunare caduta. A Relara restano forze solo per pochi respiri!", "Oh, {name}, hai salvato mia figlia! So che il potere della pietra lunare le restituirà le forze!\n\nNon potrò mai ripagarti del tutto per l'aiuto che mi hai dato, ma... ti prego, prendi questo. Dopo Relara, è la cosa a cui tengo di più.", nil, 0xa905bcf0, 0xa253d48e, 0xc1063bd4, 0x077c83f2, "m...." },
  [1037] = { nil, "Parla con Thyn'tel Bladeweaver, alla Warrior's Terrace di Darnassus.", "Velinde Starsong era la mia predecessora qui nell'Ashenvale Forest. All'inizio sembrava avere sotto controllo la situazione nella Felwood, ma a poco a poco i suoi sforzi vacillarono. Un giorno, semplicemente, scomparve.\n\nSono stata mandata qui per continuare il suo lavoro. Temo però di non sapere nulla della sacerdotessa. Forse Thyn'tel Bladeweaver, una delle comandanti delle Sentinels, conosce altri dettagli sulla sua scomparsa di cui non sono stata messa al corrente.\n\nDi certo capirà l'importanza di tali informazioni.", nil, "Velinde Starsong? Che la sacerdotessa sia scomparsa tempo fa è quasi certamente cosa nota. Quanto ad altri dettagli sugli eventi che circondarono la sua partenza... servirebbe una buona ragione perché io rivelassi tali informazioni.", nil, 0x98606e25, 0x016b231b, nil, 0xe9e791ce, "m..m." },
  [1038] = { "Gli effetti di Velinde", "Cerca il diario nel forziere di Velinde, poi riportalo insieme alla chiave a Thyn'tel Bladeweaver, a Darnassus.", "Te l'ha mostrato il Tome of Mel'Thandris? Immagino che non ci sia niente di male a lasciarti esaminare le sue cose. Questa chiave ti permetterà di aprire il forziere dove abbiamo riposto le sue cose, nella caserma delle Sentinels. Teneva un diario dei suoi doveri: se c'è qualcosa da scoprire, sarà lì.\n\nDevo dirti che le Sentinels credono che avesse le sue ragioni per andarsene, e si aspettano che possa tornare da un momento all'altro. In passato la sacerdotessa ha fatto molto per guadagnarsi la nostra fiducia.", "Cosa hai scoperto?", "Sembra che la scomparsa di Velinde sia più preoccupante di quanto sembrasse all'inizio. Eppure non riesco a credere che abbia fatto una brutta fine. Forse ci converrebbe metterci in contatto con lei.\n\n{name}, visto che hai mostrato un interesse sincero per questa faccenda, vorrei chiedere il tuo aiuto.", 0x74dbac02, 0x09fb9185, 0x7dde5963, 0x7a7fed9c, 0x7a510565, "....." },
  [1039] = { "Il porto dei Barrens", "Parla con Wharfmaster Dizzywig, a Ratchet.", "Ratchet è l'unico porto dei Barrens. Molto probabilmente Velinde ha trovato a Ratchet una nave mercantile che la portasse a Blackwater Cove, ad Azeroth. Abbiamo avuto pochi rapporti con i goblin che gestiscono il porto, ma il capo del molo dovrebbe sapere qualcosa di chi arriva e chi parte.\n\nSegui la strada verso sud-est attraverso Ashenvale e ti ritroverai nei Barrens. Guarda dove metti i piedi, {name}: i guerrieri della Horde pattugliano quelle terre. Al porto però sarai al sicuro.", nil, "{race}, eh? Devo ammettere che da queste parti non ne vediamo molti come te. Cerchi qualcuno, eh? Dammi solo un momento, di sicuro l'ho scritto in uno dei miei registri.\n\nPassa un sacco di gente di qui, però, quindi dammi solo un momento.", 0xbce71855, 0x368d5e90, 0x984e6dd9, nil, 0xa9762f9c, "...m." },
  [1040] = { "Passaggio per Booty Bay", "Prendi una nave per Booty Bay e parla con il Caravaneer Ruzzgot.", "Ah sì, finalmente l'ho trovato. Avresti dovuto dirmi che era passata di qui così tanto tempo fa. Vediamo.\n\nVelinde. Ha prenotato un passaggio per Booty Bay sulla Black Osprey. Non ho niente che dica il contrario, quindi presumo che sia arrivata in porto sana e salva.\n\nNon posso esserti di molto altro aiuto, ma mi ha chiesto dei viaggi via terra da quella parte del mondo, e le ho parlato di Ruzzgot, un carovaniere che lavora a Booty Bay. Può darsi che questa Velinde abbia viaggiato con lui.\n\nOra circola. Non ho tutto il giorno per te.", nil, "Sì? Beh, non mi sembri il tipo con merce da spedire, quindi o cerchi lavoro nella mia carovana (e adesso non ci sono posti) o probabilmente stai parlando con il goblin sbagliato.\n\nAllora, quale delle due?", 0x23568846, 0x924d775e, 0x42b15a26, nil, 0x7012c387, "...m." },
  [1042] = { "La famiglia Carevin", "Parla con Jonathan Carevin, a Darkshire.", "No, non ho notizie di una certa Velinde Starsong che abbia alloggiato a Darkshire... anche se, se mi permetti, non riesco proprio a immaginare una sacerdotessa elfa della notte che prenda una stanza alla locanda, se capisci cosa intendo.\n\nQuesti uomini-lupo di cui parli, invece, sono una cosa di cui ho sentito parlare. Proprio l'altro giorno Calor è arrivato in paese con una fila delle loro teste. Lavora con la famiglia Carevin: cacciatori di demoni, non morti e altre mostruosità. Parla con Jonathan, è il capofamiglia.", nil, "Tempi bui sono questi. Notizie funeste sussurrano da ogni ramo che ondeggia, e il male si trova sotto ogni pietra.\n\nE in tempi simili, uno sconosciuto entra in casa mia e chiede dei worgen... Non chiederò perdono per i miei sospetti, solo risposte.\n\nE risposte avrò.", 0x5b4165bb, 0x260919bb, 0x60b610fd, nil, 0xa9084ff2, "...m." },
  [1043] = { "La Scythe of Elune", "Cerca tracce della Scythe of Elune, poi torna da Jonathan Carevin a Darkshire.", "La tua storia suona vera... Non capisco del tutto le tue ragioni, ma se i tuoi affari qui a Duskwood riguardano lo sterminio dei worgen nella foresta, in qualunque numero, allora posso rinunciare a capire in cambio dei risultati.\n\nC'è una miniera a sud che è stata invasa dai worgen... Sono comparsi dal nulla, ma da quanto sappiamo è lì che sono stati trovati per la prima volta.\n\nFai pure i tuoi affari, ma ti chiederei, se trovi qualcosa di importante, di condividerlo con me. Accettiamo qualunque aiuto nella nostra guerra contro il male.", "I boschi sono pericolosi per chi non è preparato. Tieni le armi a portata di mano e il cervello ancora di più, o il tuo prossimo viaggio nella foresta infestata potrebbe essere l'ultimo.", "Racconti una storia interessante, {name}. Anche se l'influenza della famiglia Carevin non basta per trovare la radice di questi problemi e risolverli una volta per tutte, faremo il possibile per contenere il numero dei worgen a Duskwood.\n\nHo già detto a Calor di farne la sua priorità.", 0x0767908c, 0x803b9a4e, 0x6cd0e968, 0x9f8262d0, 0x837fbc53, "....." },
  [1044] = { "Domande con risposta", "Torna da Thyn'tel Bladeweaver, a Darnassus.", "Terremo a freno il problema dei worgen, non temere. Il male che la tua amica ha portato nei nostri boschi sarà contenuto, e non le serbo rancore per ciò che ha fatto. In questi tempi accadono cose strane, {name}, e l'oscurità non conosce tregua.\n\nNon ti trattengo oltre. Immagino che ci siano altri che dovrebbero sapere cosa hai trovato nelle miniere di Duskwood.", nil, "Dunque è questa la sorte di Velinde? L'alta sacerdotessa sarà delusa di saperlo: prima della sua scomparsa erano buone amiche. Eppure la Scythe of Elune le era stata di certo concessa come dono dalla nostra dea, e mi turba che sia sfuggita dalle mani delle sue serve.\n\nMa questa è un'altra faccenda, per un'altra volta. Ti devo un grande ringraziamento per ciò che hai fatto.", 0x44407ecd, 0xb8c245b0, 0x8d9eb68f, nil, 0x9bb2d02d, "...m." },
  [1045] = { "La purificazione di Raene", "Uccidi 4 Bloodtooth Guard e recupera il Ran Bloodtooth's Skull per Krolg, vicino al Lake Mystral.", "Gli elfi della notte sono antichi quanto il tempo, ma la loro arroganza distrugge il loro stesso mondo. E ora distrugge anche le nostre vite. Ma questo non si può più controllare...\n\nDo molte colpe agli elfi, ma siamo comunque responsabili delle nostre azioni. Anche al di là della corruzione, siamo capaci di grande malvagità.\n\nRan Bloodtooth è una di queste malvagità. Assetato di potere, bramoso... la corruzione lo ha solo reso più forte. Il mio odio per gli elfi arde, ma non auguro il male ai loro figli, quindi dobbiamo fare giustizia tra noi.", "Hai già ucciso Ran, amico mio?\n\nNemmeno gli elfi della notte meritano davvero la sua furia. Il suo odio arde persino più del mio, ma la sua mente non gli appartiene più. È una minaccia per tutte le creature naturali di questa foresta.", "Hai fatto bene, amico mio.\n\nLa foresta è ancora contaminata, ma almeno sappiamo di aver fatto una piccola parte per restituirle il suo antico splendore. Se vorrai tornare da me, gradirei la compagnia di uno della mia specie.\n\nStammi bene. Forse le nostre tribù si incontreranno di nuovo in tempi meno violenti.", 0x30e3be54, 0x6e8f41fa, 0x326975a1, 0x15e560ac, 0x765c3955, "....." },
  [1046] = { "La purificazione di Raene", "Porta il Ran Bloodtooth's Skull e il Dartol's Rod of Transformation a Raene Wolfrunner, ad Astranaar.", "Torna dalla tua tribù e fai sapere loro della tua vittoria qui.\n\nMostra loro il tuo trofeo e crogiolati nella gloria...", "Le Sentinels fanno quel che possono qui ad Ashenvale, ma è grazie a quelli come te, {race}, che abbiamo guadagnato il terreno che abbiamo.", "Quindi questo è il teschio della più feroce minaccia furbolg di Ashenvale?\n\nSono più che soddisfatta delle tue capacità, {name}. Le Sentinels non potranno mai ringraziarti abbastanza. Spero di poter contare ancora su di te in futuro per aiutare la nostra gente.\n\nMetterò questo teschio e il Dartol's Rod in un luogo di venerazione, perché altri possano vederli.\n\nTeronis sarebbe fiero. Grazie ancora.", 0x30e3be54, 0x331416f0, 0xe5eec590, 0x96cede1d, 0xdaa0c8c3, "....." },
  [1047] = { "La nuova frontiera", "Parla con Arch Druid Fandral Staghelm nel Cenarion Enclave di Darnassus della chiamata del Cenarion Circle a esplorare le frontiere di Kalimdor.", "Attenzione, eroi!\n\nIl Cenarion Circle cerca persone abili che lo aiutino a esplorare le vaste nuove frontiere di Kalimdor! Una terra desolata e proibita, piena di pericoli inimmaginabili, si trova molto a ovest di Tanaris e di Gadgetzan, e il Circle ha bisogno di rappresentanti volenterosi e onorevoli che agiscano al suo posto.\n\nTutti gli interessati dovrebbero chiedere udienza al Cenarion Circle. Parlate con l'arcidruido di Darnassus, Fandral Staghelm, per maggiori informazioni!", nil, "Cosa ti fa pensare che io voglia essere importunato da gente come te, {class}? Aspetta, lascia che interrompa i doveri importanti di cui mi occupo ogni giorno per aiutarti a trovare un aggeggio da qualche parte. Ma certo, il benessere di Darnassus, anzi, di tutta Teldrassil, deve venire dopo l'acquisto di un ninnolo per la tua collezione.\n\nQuegli sciocchi di Moonglade mi fanno perdere tempo con la loro richiesta di aiuto, e ora devo sopportare anche questo?", 0x980efd04, 0x419bdcfb, 0x5f025126, nil, 0xc02ec71d, "...m." },
  [1052] = { "Lungo il sentiero scarlatto", "Porta la Brother Anton's Letter of Commendation a Raleigh the Devout, a Southshore.", "Noi della Scarlet Crusade rivendichiamo roccaforti da Hearthglen alle Tirisfal Glades. Siamo molto fieri dei nostri bastioni di purificazione in tutta Lordaeron.\n\nHai dato prova di te contro i non morti a Desolace. Ma la vera minaccia della piaga è a Lordaeron.\n\nRecati nella città di Southshore, negli Eastern Kingdoms. Cerca un crociato di nome Raleigh the Devout. Dagli questa lettera di encomio con il mio sigillo e ti accompagnerà a un posto d'onore nel nostro Scarlet Monastery.", "Chi va là? Cosa vuoi da me?", "Il Brother Anton diffonde ancora il verbo della Scarlet Crusade? Oh, cielo....", 0xaeca3093, 0x57a21639, 0xacd22c21, 0x1efda351, 0xc98191de, "....." },
  [1053] = { "Nel nome della Luce", "Uccidi l'High Inquisitor Whitemane, lo Scarlet Commander Mograine, Herod, the Scarlet Champion e l'Houndmaster Loksey, poi torna a fare rapporto a Raleigh the Devout, a Southshore.", "Un tempo servivo la Scarlet Crusade con onore, lealtà e orgoglio. Credevo che la loro causa fosse nobile: liberare Azeroth dai non morti.\n\nMa durante il tempo trascorso al Monastery nelle Tirisfal Glades mi resi conto che stavano perdendo il contatto con la realtà. Ora pensano che chiunque non indossi la tabarda della Crusade sia appestato. Uomini e donne innocenti sono stati torturati perché presunti appestati.\n\nLa Scarlet Crusade deve essere schiacciata nel nome della Luce. Tu, {name}, devi distruggere quel regime folle.", "La corruzione nel Monastery non finirà finché non saranno rimossi i più alti ufficiali.\n\nNel nome della Luce, uccidi l'High Inquisitor Whitemane, lo Scarlet Commander Mograine, Herod, the Scarlet Champion e l'Houndmaster Loksey. Una volta caduti, forse la vera causa potrà riaccendersi. Fino ad allora, chiunque incroci il cammino della Crusade è in pericolo.\n\nParti da Southshore e fa' che sia così!", "Anche se i discepoli della Luce non gioiscono mai della perdita di vite, dobbiamo accettare che, a volte, tali sacrifici siano necessari per il bene superiore del regno e del pianeta.\n\nCon le tue imprese nel Monastery hai risparmiato molte vite innocenti, {name}. Rendo onore alla tua tenacia.", 0x90a29d76, 0x55b9e680, 0xa8cc842d, 0xb5e3d9d7, 0xefc4c627, "....." },
  [1054] = { "Ridurre la minaccia", "Porta il Dal Bloodclaw's Skull a Raene Wolfrunner, ad Astranaar.", "Direttamente a nord di Astranaar ci sono i furbolg Thistlefur. I miei esploratori riferiscono che il loro numero è cresciuto molto negli ultimi mesi. Se diventano troppi, potrebbero trovare il coraggio di attaccare direttamente Astranaar.\n\nUccidine quanti più puoi, ma portami il teschio del loro capotribù come prova che i loro sforzi sono stati soffocati... per ora.\n\nResterò qui ad Astranaar in attesa di tue notizie. Che Elune sia con te.", "La corruzione dei furbolg ha ridotto Ashenvale a una frazione del suo antico splendore.", "Ben fatto, {name}.\n\nSiamo costantemente minacciati dai furbolg. Speriamo che questo li tenga a bada ancora per un po'.", 0xc9327026, 0x0cf5cd78, 0xbc890332, 0xc10729bc, 0x94c3bc40, "....." },
  [1055] = { "La purificazione di Raene", "Torna da Shael'dryn al pozzo lunare.", "La verga, ora completa, è nelle tue mani. Shael'dryn vorrà sapere del tuo successo.", nil, "Ce l'hai fatta, {name}! Ben fatto!", 0x30e3be54, 0xa7333bfb, 0x652f01d5, nil, 0x9327f633, "...m." },
  [1056] = { "Viaggio verso lo Stonetalon Peak", "Recati dal Keeper Albagorm, sullo Stonetalon Peak.", "Gli spiriti della foresta mi dicono che sei <coraggioso/coraggiosa> e <disposto/disposta> a viaggiare.\n\nA sud, non lontano dal Mystral Lake, c'è una galleria chiamata The Talondeep Path. Attraverso questa galleria arriverai in una zona nota come Windshear Crag, nelle Stonetalon Mountains. Una volta lì, procedi verso sud-ovest oltre il Cragpool Lake e poi a nord, su per il ripido pendio, fino a raggiungere lo Stonetalon Peak.\n\nLì ti attende il Keeper Albagorm. Segui le sue istruzioni, {race}.\n\nIl viaggio sarà pericoloso.", nil, "Finalmente sei <arrivato/arrivata>. Vedo che Faldreas ha ascoltato gli spiriti della foresta....", 0xb967664b, 0xecb8a211, 0xb0111aba, nil, 0x3ad69b06, "...m." },
  [1057] = { "Riconquistare la Charred Vale", "Il Keeper Albagorm, sullo Stonetalon Peak, vuole che tu uccida 6 Bloodfury Harpies, 6 Bloodfury Ambushers, 6 Bloodfury Slayers e 6 Bloodfury Roguefeathers.", "Come <protettore/protettrice> degli spiriti della foresta, puoi certo immaginare perché io sia in allarme.\n\nHai attraversato queste montagne per raggiungere questa vetta. Di sicuro hai visto lo scempio che si è abbattuto su questa terra. L'avidità ha portato alla distruzione di queste colline sacre.\n\nLa Charred Vale, a sud, è stata data alle fiamme dall'avido esercito meccanizzato degli industriali. Peggio ancora, le Bloodfuries che hanno invaso la zona ci negano il passaggio per avviare la rinascita.\n\nScaccia quelle arpie infami, {name}!", "C'è molto lavoro da fare prima che la Charred Vale torni a essere la foresta rigogliosa di un tempo.\n\nLibera la zona da quelle minacce immonde, {name}! Solo allora potremo cominciare a riconquistare ciò che appartiene alla natura.", "Ora che le Bloodfuries hanno subito una perdita così grande, forse può cominciare il vero lavoro di risanamento della terra....", 0x3dc3d0c0, 0xe2dfdbfc, 0x38e3847a, 0x64c961c6, 0x08e244c5, "....." },
  [1059] = { "Riconquistare la Charred Vale", "Recati da Falfindel Waywarder, al confine tra Thousand Needles e Feralas.", "Le Bloodfuries sono state domate. Ma si riorganizzeranno presto se non si interviene.\n\nMolto a sud delle Barrens si trova una terra nota come Thousand Needles. Se viaggi verso ovest a Thousand Needles fino al margine della rigogliosa foresta di Feralas, troverai un druido di nome Falfindel Waywarder.\n\nQuesto grande e saggio druido è capace di evocare grandi spiriti della foresta che possono aiutare a riconquistare la Charred Vale.\n\nFagli sapere del nostro bisogno! Cercalo subito!", nil, "Il Keeper Albagorm è stato saggio a mandarti con tanta urgenza.\n\nVediamo se riusciamo a invocare l'aiuto della grande foresta perché raggiunga la Charred Vale prima che sia troppo tardi.", 0x3dc3d0c0, 0x9d2cf9a3, 0xc8c5b4c2, nil, 0x1237db66, "...m." },
  [1069] = { "Uova di ragno Deepmoss", "Porta 15 Deepmoss Eggs a Mebok Mizzyrix, a Ratchet.", "Le omelette di uova di ragno sono la nuova moda a Booty Bay! Il problema è che... a Booty Bay non ci sono uova.\n\nSento odore di affari!\n\nA Windshear Crag e nel Sishir Canyon, nelle Stonetalon Mountains a nord-ovest, vive il ragno deepmoss. Portami le sue uova e ti pagherò un sacco!\n\nA Windshear Crag, le uova sono ammassate sotto gli alberi rimasti.\n\nNel Sishir Canyon... beh, se hai lo stomaco debole forse dovresti limitarti a raccogliere le uova a Windshear Crag...", "Hai preso le uova, {name}? Ho già concluso un accordo di spedizione con il Wharfmaster Dizzywig!", "Le hai prese! Grazie!\n\nLe farò mandare a Dizzywig e spedire a Booty Bay. Sento già il sapore dei profitti!\n\nEcco la tua parte, {name}. Non avrei potuto concludere questo affare senza di te.", 0x14d2d688, 0xf245c60e, 0x270b2709, 0x883bef30, 0x74f54230, "....." },
  [1070] = { "Di guardia a Stonetalon", "Trova Kaela Shadowspear, che sorveglia la valle all'ingresso di Windshear Crag, nelle Stonetalon Mountains.", "Salve, {name}.\n\nA guardarti, sembri <pieno/piena> di voglia di viaggiare. Sei mai <stato/stata> nelle Stonetalon Mountains? È una terra afflitta dalla Venture Co. e da altri nemici degli elfi della notte.\n\nDi recente la Sentinel Wolfrunner vi ha mandato la mia amica Kaela Shadowspear per indagare su ciò che sta accadendo a quella terra, ma non ho ancora avuto sue notizie. Sono ancora più preoccupata perché l'Alliance ha mandato con lei un mago gnomo... sicuramente un segno di guai.\n\nLa troverai e mi riferirai?", nil, "Ah, vieni da Ashenvale su richiesta di Tara... quanto mi mancano lei, la mia terra natale e i miei amici. Deve cavarsela bene con le Sentinels, se arruola avventurieri per altri compiti. Sono fiera di lei.\n\nÈ un piacere conoscerti, {name}.", 0xf1b5310d, 0x9ed94a98, 0xee657ad7, nil, 0x44b73423, "...m." },
  [1071] = { "La tregua di uno gnomo", "Uccidi 10 Venture Co. Logger e 10 Venture Co. Deforester e torna da Gaxim Rustfizzle, a Stonetalon.", "Vedi, {name}, sono membro dell'Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences, e il mio obiettivo... anzi, il mio dovere! è dimostrare agli elfi della notte che un miscuglio di magia, misture e meccanismi può aiutare a salvare le loro foreste.\n\nMa è una guerra dura, e pare che i goblin si riproducano come conigli. Non ho avuto nemmeno il tempo di costruire le mie nuove invenzioni!\n\nMi serve un po' di tempo per pianificare e organizzarmi. Ma per farlo ho bisogno del tuo aiuto per tenere a bada i goblin a Windshear Crag, a est...", "Come va la battaglia dalla tua parte, {name}?", "Grazie mille per il tuo aiuto, {name}. Anzi, sei <tornato/tornata> proprio al momento giusto.\n\nCredo di avere un piano perfetto... esplosivi. No, il piano non è questo, ma ne fa parte.\n\nVedi, ho usato esplosivi ad alto potenziale (non preoccuparti, non sono pericolosi come tutti pensano) per far arretrare un po' i goblin. Riesco a guidarli piuttosto bene con qualche detonazione mirata lungo i fianchi delle montagne, ma da qualche giorno sono a corto di scorte...", 0x81885f31, 0x39875a59, 0x4f827ebf, 0x8ed33a78, 0x1460c1f4, "....." },
  [1072] = { "Un vecchio collega", "Parla con Lomac Gearstrip, a Ironforge.", "Il congegno a cui penso è la mia versione più avanzata finora. Ma per farlo funzionare ci servirà una pozione speciale. Penso che tanto valga prendere la roba buona, visto che questa missione potrebbe essere la tua ultima.\n\nE per questo ci serviranno esplosivi potenti: Nitromirglyceronium.\n\nL'unica persona capace di fare l'NG-5 è un mio vecchio amico: Lomac Gearstrip. Cercalo a Tinker Town.\n\nTu convincilo a prepararci un po' di NG-5, io mi metterò al lavoro sul posizionamento dei miei congegni.", nil, "Ahhh.... ti ha mandato Gaxim, eh? Come faccio a sapere che non mi stai mentendo?! Eh? Eh...?", 0xad49e719, 0xa710c50b, 0x2f2357b3, nil, 0xcaefb60e, "...m." },
  [1075] = { "Una pergamena da Mauren", "Trova Collin Mauren a Stormwind.", "Bene, ora la parte del mio piano sulla detonazione a distanza... oh, non te l'ho ancora spiegata, vero?\n\nBene, in breve è così: con un pizzico di magia posso far sì che gli esplosivi saltino quando tu non sei nei paraggi. Sto assemblando un congegno che ti permetterà di premere un solo pulsante e far esplodere l'NG-5 quando sarai <pronto/pronta>.\n\nMa mi serve un incantesimo da un amico a Stormwind: si chiama Collin Mauren. Lo trovi nel quartiere dei maghi. È umano, quindi non dovrebbe essere difficile notarlo.", nil, "Allora, questo incantesimo che ti serve: uno che ti permetta di far detonare esplosivi a distanza... mmm.", 0x58c40a09, 0x1b3699f4, 0xf43ca5a0, nil, 0x723899cb, "...m." },
  [1076] = { "Diavoli a Westfall", "Porta i Dust Devil Debris a Collin Mauren, a Stormwind.", "Ah, credo di aver capito. Un incantesimo di messaggio... credo sia l'effetto che cerca.\n\nDovrò creare una pergamena con l'incantesimo impresso sopra. Per farlo mi serviranno i detriti di un dust devil.\n\nMentre raccolgo il resto dei componenti, perché non vai a Westfall a cercare una di quelle immonde creature? Sono pericolose, ma sono sicuro che non è niente che tu non sappia gestire, se sei <disposto/disposta> a sottoporti a uno degli esperimenti di Gaxim.\n\nSarò qui al tuo ritorno.", "Salve, {name}. Hai trovato il componente che mi serve?", "Concedimi qualche istante e la tua pergamena sarà pronta.", 0xf0e28ebb, 0x2aa2e96c, 0x3e02eba9, 0x7f60f7de, 0x19cadc30, "....." },
  [1077] = { "Consegna speciale per Gaxim", "Porta lo Scroll of Messaging a Gaxim Rustfizzle, a Stonetalon.", "Ecco a te, {name}. Dovrebbe andare benissimo.\n\nPorta i miei saluti a Gaxim la prossima volta che lo vedi. Non vedo l'ora di sentire di questa avventura quando sarà giunta al termine.\n\nStammi bene.", "Ahah! Sei <tornato/tornata>! Ce l'hai? Hai l'incantesimo?", "È perfetto, {name}! Ben fatto.\n\nQuesto incantesimo, unito all'NG-5, creerà l'esplosivo a distanza perfetto.\n\nPotremo creare il diversivo perfetto perché tu possa intrufolarti e rubare le lettere e i progetti di ingegneria della Venture Co.\n\nQuesto rallenterà di sicuro la loro opera di disboscamento.", 0xd1462095, 0x51ae1c5d, 0x1b8d59b2, 0xdd1faf10, 0xbe0ac519, "....." },
  [1078] = { "Una raccolta per Mauren", "Porta 8 Crystalized Scales a Collin Mauren, a Stormwind.", "I viaggiatori continuano a chiedermi delle Stonetalon Mountains. Sembra un luogo molto amato per le avventure: che tu cerchi viverne, elementali o abbia affari con la Venture Co., non fa differenza.\n\nNella Charred Vale, nel cuore di Stonetalon, un tempo viveva una specie di basilischi le cui scaglie, ridotte in polvere, erano un reagente meraviglioso per alcuni incantesimi che ho creato.\n\nSe quei basilischi vivono ancora, mi piacerebbe avere qualcuna delle loro scaglie.\n\nFa' con calma, non c'è fretta, ma posso pagare bene.", "Salve di nuovo, {name}.\n\nSei già <tornato/tornata> dalla Vale di Stonetalon con quelle scaglie?", "È perfetto, {name}. Grazie infinite.\n\nForse un giorno, in futuro, potrò aiutarti come tu hai aiutato me.", 0xf7d838e2, 0x2360a1f8, 0xc942697b, 0x291f5038, 0xdba69ed3, "....." },
  [1079] = { "Operazioni segrete - Alpha", "Recupera i Venture Co.'s Engineering Plans dalla segheria di Windshear Crag.", "Ci siamo, {name}. Ascolta bene. I congegni sono pronti e possono essere usati.\n\nPrendi queste pagine: ti spiegheranno meglio i detonatori e gli esplosivi, e dove piazzarli.\n\nRicorda, il successo della tua missione non dipende da quanta distruzione causi. Il successo del Plan Alpha dipende dal fatto che tu riporti gli Engineering Plans della Venture Co. dall'interno della segheria a sud del Cragpool Lake.", "Hai preso i progetti, {name}?", "Davvero straordinario! È un duro colpo per la Venture Co.\n\nPotremo trovare i punti deboli delle loro macchine e incorporare i loro progetti nelle nostre creazioni. È davvero un giorno meraviglioso.", 0x67625d6d, 0xdbfd5680, 0x4c8cfe7c, 0x7e92c08b, 0xf3532bc5, "....." },
  [1080] = { "Operazioni segrete - Beta", "Recupera le Venture Co. Letters dalla Windshear Mine, all'estremità orientale di Windshear Crag.", "Il Plan Beta è proprio come il Plan Alpha, {name}.\n\nCreiamo un diversivo e poi rubiamo le loro preziose lettere.\n\nLa cosa fondamentale è prendere le lettere... ricordalo.\n\nLe pagine che ti ho già dato ti diranno dove piazzare gli esplosivi. Basta che torni qui <vivo/viva> e con quelle lettere....", "Com'è andata, {name}?", "Incredibile, {name}! Kaela e le Sentinels saranno felicissime. Con la tua abilità e le mie creazioni siamo inarrestabili.", 0x435bdad7, 0xaaab2588, 0xd5c09f15, 0x30cd8aea, 0xea15a34a, "....." },
  [1081] = { "Udienza da Tyrande", "Trova Tyrande Whisperwind a Darnassus.", "{name}, sono certa che la stessa Tyrande Whisperwind vorrà ringraziarti per aver preso parte a questa missione.\n\nIn superficie potrebbe non sembrare, ma ciò che hai contribuito ad avviare potrebbe benissimo rafforzare la nostra presenza nelle Stonetalon Mountains.\n\nSe ti consideri <nostro/nostra> <alleato/alleata> contro queste atrocità, va' da Tyrande nel Temple of the Moon, a Darnassus.", nil, "Salve, {name}. Ho davvero già sentito il tuo nome, e anche se sei ancora nel fiore della giovinezza, sono lieta di vedere il cammino che hai intrapreso.\n\nMi faresti un grande onore se accettassi questo come dono di riconoscenza.", 0x2ecc6a2b, 0xbb227158, 0x02acff07, nil, 0x42a56151, "...m." },
  [1082] = { "Aggiornamento per la Sentinel Thenysil", "Torna dalla Sentinel Thenysil, ad Ashenvale.", "{name}, hai compiuto una grande impresa dando una mano qui.\n\nLe Sentinels di Ashenvale ti ricompenseranno bene se farai sapere loro che Gaxim e io siamo vivi. Di' loro che siamo sulla buona strada per fermare la Venture Co. e risanare queste terre.\n\nTrova Tara Thenysil ad Astranaar: sarà lieta di vederti tornare con buone notizie.", nil, "Grazie, {name}. Hai reso un servizio alle Sentinels.\n\nSono lieta di sapere che Kaela... e persino Gaxim stanno bene.\n\nTi sei <guadagnato/guadagnata> la nostra riconoscenza.", 0x8cbe9e1c, 0xa02009ab, 0x0efa59cf, nil, 0xb214a8e6, "...m." },
  [1083] = { "Spiriti infuriati", "Porta 8 Smoldering Embers, presi da qualsiasi elementale del fuoco della Charred Vale, a Kaela Shadowspear, a Stonetalon.", "Non so cosa abbia fatto la Venture Co. alla Vale, ma è chiaro che è stata sopraffatta dalle creature del posto.\n\nHanno dato fuoco alla foresta e usato le loro invenzioni distruttive per devastare quanto più possibile della Vale.\n\nMa nella loro ignoranza hanno liberato anche qualcos'altro: spiriti ardenti, elementali di fiamma, pietra e furia.\n\nQuesta terra non avrà alcuna speranza di vedere il sorriso di Elune finché queste creature vagheranno libere.\n\nPortami i loro tizzoni ardenti per dimostrare che ne hai ridotto il numero.", "La prima volta che ho visto la Charred Vale ho quasi pianto, {name}.", "I resti del nostro nemico... la tua forza ci è preziosa, {name}. Grazie.", 0x541e782d, 0x32646144, 0x91e83ed1, 0x4ab60f8c, 0x584d2d40, "....." },
  [1084] = { "Antichi feriti", "Porta un pezzo di Corroded Shrapnel a Kaela Shadowspear, a Stonetalon.", "Mi sembra ovvio che i protettori della Vale, i treant, abbiano avuto a che fare con la ritirata della Venture Co. Purtroppo, anche quei guardiani un tempo grandi sono ora corrotti.\n\nGaxim pensa che la loro corruzione sia in qualche modo legata alle armi usate dai goblin durante la ritirata.\n\nGli ho detto che avrei raccolto un campione da un treant ferito per permettergli di studiarlo e capire se è così.\n\nPortami un po' di schegge, così lo gnomo potrà dirmi di più...", "Ho la sensazione che Gaxim troverà un uso per le schegge, indipendentemente da come le abbia usate la Venture Co. in passato.", "Grazie, {name}.\n\nQuesto dovrebbe bastare e avanzare perché Gaxim capisca come sono stati corrotti i treant. Glielo darò subito.", 0x00a0d96c, 0x41c21b98, 0x08fc2949, 0x1516aa6d, 0x95a6d4f4, "....." },
  [1085] = { "Di guardia a Stonetalon", nil, nil, nil, nil, 0xf1b5310d, nil, nil, nil, nil, ".mmmm" },
  [1090] = { "Gli ordini di Gerenzo", "Prendi il minerale misterioso da Piznik quando avrà finito di estrarlo.", "Sai, un tempo ero la seconda persona più importante di questo cantiere. Tutto è cambiato quando è arrivato Gerenzo. Ha licenziato il mio capo, Ziz Fizziks, e ha mandato me a lavorare nelle miniere. Ziz però mi ha detto di restare qui a raccogliere informazioni. Il suo nuovo capo ci pagherà bene se riusciamo a scoprire i piani di Gerenzo.\n\nComunque, quel che so è che Gerenzo ha ordinato di estrarre grandi quantità di questo minerale verde-oro. Posso procurarti un campione da portare a Ziz, ma dovrai guardarti dalle pattuglie mentre lo prendo.", nil, "Grazie, {name}. Per un attimo la cosa si è fatta un po' rischiosa e probabilmente abbiamo attirato fin troppa attenzione.\n\nLa cosa importante, però, è che abbiamo il campione di minerale, e dovremmo portarlo a Ziz il prima possibile.", 0xce6824bd, 0x17fb1d28, 0x30d3cff4, nil, 0x96af83cc, "...m." },
  [1091] = { "Notizie da Kaela", "Porta le Venture Co. Letters a Kaela Shadowspear.", "{name}, porta queste lettere a Kaela. Sono sicuro che vorrà saperlo. O almeno le Sentinels lo vorranno.\n\nAssicurati di dirle che successo abbiamo avuto e che non ce l'avremmo fatta senza un pizzico di magia.", "Sì, {name}? Cosa posso fare per te?", "È davvero interessante.\n\nTu e Gaxim avete fatto un ottimo lavoro, {name}. Grazie.", 0x2303e574, 0x88de288b, 0xcc598924, 0x1573cda6, 0xcb79207d, "....." },
  [1092] = { "Gli ordini di Gerenzo", "Consegna l'Unidentified Ore a Ziz Fizziks, nelle Stonetalon Mountains.", "Credo che sia meglio che anch'io pensi ad andarmene da qui. Non ci vorrà molto perché la notizia di quanto è successo arrivi ai piani alti, e sono sicuro che non sarebbero molto felici di rivedermi.\n\nSgattaiolerò fuori e raggiungerò Ziz. Speriamo che riesca a trovarmi un nuovo lavoro!\n\nCercherò di ripulire un po' questo disastro, ma tu dovresti portare subito il campione di minerale a Ziz. Mi ha detto che si sarebbe accampato da qualche parte sul lato occidentale di Windshear Crag. Buona fortuna.", "Posso aiutarti in qualcosa?", "Ahhh, sapevo di aver fatto la cosa giusta dicendo a Piznik di restare indietro. Sono sicuro che gli ingegneri di Undermine saranno molto interessati a esaminarlo...\n\nNaturalmente ne terrò un pezzetto per me, ma occhio non vede, cuore non duole, giusto?", 0xce6824bd, 0x5ff378be, 0xe65a92f9, 0xdf112bb5, 0x1883fb16, "....." },
  [1093] = { nil, "Procura i Super Reaper 6000 Blueprints per Ziz Fizziks, nelle Stonetalon Mountains.", "Terribile quello che la Venture Company ha fatto qui, eh? Che cosa pensavano? Una compagnia goblin che assume uno gnomo!\n\nPer mia fortuna, Sputtervalve riconosce un genio quando lo vede. Mi ha assunto subito dopo che mi avevano cacciato!\n\nMi dice che hanno costruito un'enorme macchina taglialegna, e Sput' vuole che gli rubi i progetti. Purtroppo Gerenzo, maledetto gnomo, vuole vedermi morto appena mi vede... forse potresti rubare i progetti per me? Dovresti trovarli addosso a uno dei loro operatori.", "Hai trovato quei progetti? Non vedo l'ora di fare colpo sul nuovo capo. Spero che, una volta convinto della mia lealtà (beh, per quanto si possa convincere... parola di goblin, sai?), si sentirà tranquillo nello sfruttare il mio genio piuttosto notevole.", "Ehi, è quello che penso? Ottimo!\n\nDunque, vediamo. Uff... come faccio a capire questa roba... non riesco a capire come ragionano gli gnomi. Lascia che te lo dica, mi stupisce che siano riusciti a inventare la ruota, figuriamoci quelle macchine volanti che amano tanto.", nil, 0xfe2d59bd, 0xad532ea7, 0x7a6f86e7, 0x7531d6d0, "m...." },
  [1094] = { "Ulteriori istruzioni", "Consegna la Sealed Envelope a Sputtervalve, nelle Barrens.", "Questa busta contiene tutte le informazioni che sono riuscito ad arraffare mentre mi buttavano fuori dalla porta... documenti interni della Venture Company, qualche manuale, cose tecniche... Oh, e naturalmente i progetti del Super Reaper 6000.\n\nSputtervalve si è stabilito a Ratchet, nelle Barrens. Non dovresti avere problemi a trovarlo: è un tipetto verde.", "Salve! Come posso aiutarti?", "Fizziks, eh? Non posso dire di fidarmi di lui, ma queste informazioni sembrano abbastanza buone. Cosa non darei per togliermi di torno la Venture Company.\n\nPerò inventano delle buone macchine... non posso negare che abbiamo tratto vantaggio da alcuni dei miglioramenti che hanno ideato.", 0xd12c0eee, 0xc9ab2557, 0xb0912f98, 0x73864487, 0xd6844379, "....." },
  [1095] = { "Ulteriori istruzioni", nil, nil, nil, nil, 0xd12c0eee, nil, nil, nil, nil, ".mmmm" },
  [1096] = { nil, "Porta il Gerenzo Wrenchwhistle's Mechanical Arm a Ziz Fizziks, nelle Stonetalon Mountains.", "Ho incontrato Gerenzo una volta, e lascia che te lo dica, non è un bel vedere. La sua carne sembra in putrefazione, e si è innestato metallo e ingranaggi sul corpo, sostituendo alcuni arti con arti meccanici.\n\nA nord-est di qui, molto più in alto del Cragpool Lake, vicino alla ruota idraulica, è da lì che Gerenzo sorveglia l'intero cantiere. Non c'è modo che io riesca ad aprirmi la strada combattendo fin lassù, figuriamoci affrontare Gerenzo... Ma tu sembri in grado di farcela.\n\nSe lo uccidi per me, ne varrà la pena!", "Sputtervalve vorrà una qualche prova che Gerenzo è morto. Credo che il suo braccio meccanico andrà bene.", "Guarda quell'affare... solo uno gnomo poteva inventare una cosa del genere. Non capisco perché uno dovrebbe tagliarsi un braccio e sostituirlo con quello, quando potrebbe tenersi entrambe le braccia e aggiungerne un terzo!\n\nGnomi, te lo dico io...\n\nAlmeno Gerenzo è fuori gioco. Speriamo che basti come prova e che Sputtervalve mi assegni a uno dei laboratori della Tinkers' Union a Gadgetzan, o magari persino a Undermine.", nil, 0xf0c79254, 0x2e6098b0, 0xe15dc320, 0xfc121249, "m...." },
  [1097] = { "Il compito di Elmore", "Parla con Grimand Elmore.", "C'è un fabbro d'armi nanico a Stormwind, Grimand Elmore, che ha fatto sapere che gli serve aiuto per una consegna. Credo voglia spedire un pacco nella sua patria, al nord.\n\nHai un bel paio di gambe robuste! Quindi, se ti va di camminare un po', parla con Grimand. Qui ci servi, ma dobbiamo anche mantenere saldi i legami con i nani.\n\nTrovi Grimand Elmore nella bottega d'armi del Dwarven District di Stormwind, nella parte nord-est della città.", nil, "Sei qui per aiutarmi con la consegna? Molto bene!", 0x30749260, 0x6ac05387, 0xf12b5a6f, nil, 0x7d006a0a, "...m." },
  [1103] = { "Il richiamo dell'acqua", nil, nil, nil, nil, 0x1f0e11aa, nil, nil, nil, nil, ".mmmm" },
  [1112] = { "Pezzi per Kravel", "Porta i Kravel's Parts a Kravel Koalbeard, negli Shimmering Flats.", "Ecco il pacco di Kravel, {name}. E quando glielo consegni, digli... che se vuole altri ordini speciali, dovrà saldare il suo conto!", "Sei <arrivato/arrivata> a Ratchet e hai preso quei pezzi?", "Ottimo, li hai presi! Ora dobbiamo portarli agli gnomi. Ma prima...\n\nTogliamo un piccolo pezzo...", 0xa7b09232, 0x2dab0b5b, 0xbb280b93, 0xe5299e30, 0x2a306b0a, "....." },
  [1123] = { nil, "Parla con Rabine Saturna nel villaggio di Nighthaven, a Moonglade. Moonglade si trova tra Felwood e Winterspring, raggiungibile con un sentiero che parte dalla Timbermaw Hold.", nil, nil, nil, nil, 0x2d1faec5, nil, nil, nil, "m.mmm" },
  [1124] = { "Terra desolata", "Parla con Layo Starstrike vicino al cimitero di Valor's Rest, a Silithus, mostrandogli la Rabine's Letter.", "A ovest dell'Un'Goro Crater, attraverso la cresta nord-occidentale, si trova una terra desolata e ostile: Silithus. In pochi sanno che lì si combatté un'antica guerra tra gli elfi della notte e un potere alieno e maligno. Il male fu sigillato, ma ora sospettiamo che alcune forze stiano lavorando per risvegliare questo... orrore indicibile.\n\nCerca Layo Starstrike, uno dei nostri agenti a Silithus; lo troverai a Valor's Rest, l'ultima dimora dei caduti di quelle terre desolate. Dagli questa lettera e ti accorderà la sua fiducia.", "Questa è una terra pericolosa per essere così sbadati, {class}. Cosa ti porta nelle terre desolate di Silithus?", "Ti ha mandato Rabine, eh? Beh, considerati <benvenuto/benvenuta> qui... per quanto questa terra desolata e abbandonata possa dare il benvenuto a qualcuno.\n\nNon ero vivo ai tempi delle grandi tribolazioni che si svolsero qui, ma ci sono parti di questo deserto che sembrano immagini inquietanti di quel passato dimenticato. Con il tuo aiuto, il Cenarion Circle potrebbe riuscire a porre fine a una minaccia che sarebbe dovuta morire generazioni fa.", 0xf22898d5, 0x87046503, 0xaeb0ca1a, 0x82dd9796, 0xc25500fb, "....." },
  [1132] = { nil, "Parla con Fiora Longears, a Theramore.", "Oh, essere di nuovo in mare! Sentire il bacio del vento, e farmi cullare dalle onde come dalla mia benedetta madre, tanto tempo fa!\n\nOh, vorrei avere la tua fortuna, buon {class}, perché vedo il mare nel tuo futuro!\n\nIl mio lavoro è parlare alle anime desiderose della terra di Kalimdor, la terra delle opportunità! Se vuoi tentare la fortuna oltre il mare, prendi una nave da qui per il bel porto di Theramore. Lì parla con la mia socia, l'elfa Fiora Longears.\n\nTi farà cominciare la tua avventura a Kalimdor!", nil, "Buongiorno a te! Ti manda Mr. Flint di Menethil Harbor? Be', Mr. Flint sa giudicare le persone. Se ti ha mandato lui, non c'è dubbio che il tuo posto sia qui a Kalimdor!", nil, 0x79d16431, 0x1e6af9aa, nil, 0xf87f590d, "m..m." },
  [1134] = { "I pridewing di Stonetalon", "Porta 12 Pridewing Venom Sacs a Shindrell Swiftfire, ad Astranaar.", "Non siamo in guerra aperta con l'Horde, ma la nostra pace è fragile. Spesso troviamo loro agenti che agiscono contro di noi, ma lo fanno di nascosto.\n\nUna di queste mosse ci è stata rivelata da fonti segrete a Theramore, secondo cui gli orchi raccolgono il veleno dei pridewing vicino al Mirkfallon Lake, nelle Stonetalon Mountains a sud. Gli assassini orchi usano poi il veleno nelle loro incursioni segrete e mortali contro l'Alliance!\n\nSe è vero, dobbiamo fermarli, {name}. Dobbiamo privarli della loro fonte di veleno.", "Hai le sacche di veleno di pridewing, {name}? Non possiamo permettere agli orchi di usare i veleni di quelle bestie contro di noi!", "Grazie, {name}. Mi rattrista ordinare il massacro di creature che forse non aiutano volontariamente i nostri nemici, eppure è mio dovere farlo.\n\nIl tuo cuore potrà piangere per i pridewing che hai ucciso, amico mio, ma possa poi gonfiarsi sapendo che i tuoi alleati sono al sicuro dal loro veleno.", 0xa7c7d697, 0x11cffadd, 0xf879268d, 0x5e83f83e, 0xcd6cbd25, "....." },
  [1138] = { "Frutti di mare", "Raccogli 6 Fine Crab Chunks per Gubber Blump, ad Auberdine.", "Adoro il granchio. I granchi sono i frutti del mare! Puoi cuocerlo al forno, alla brace, bollirlo, grigliarlo. Fritto in padella, fritto in olio, saltato. C'è l'insalata di granchio, la zuppa di granchio, lo stufato di granchio, il granchio al pepe, il granchio al limone, il granchio alla whipper root e il granchio sorpresa di Ironforge. E... e basta, credo.\n\nOra sono qui a pescare, quindi non posso prendere le Fine Crab Chunks. Puoi prenderle dai reef crawler e dagli encrusted tide crawler. Ci puoi fare un sacco di cose. Puoi cuocerlo al forno, alla brace, bollirlo...", "...granchio al limone, granchio alla whipper root e granchio sorpresa di Ironforge. Più o meno è tutto.\n\nOh, salve, {name}. Hai quei fine crab chunks di cui ti parlavo?", "Accidenti, questi fine crab chunks sono proprio quel che mi serve. Grazie, {name}! Ho trovato questo mentre pescavo tempo fa e non mi serve a niente. Forse tu puoi farci qualcosa. Di sicuro non ci si fanno dei buoni piatti di granchio.\n\nTi ho raccontato tutto sui granchi, vero?", 0xcf90f28d, 0x836c5e9a, 0x029859ec, 0x81c4ae4d, 0x4d6e1f4b, "....." },
  [1140] = { "La Tower of Althalaxx", nil, nil, nil, nil, 0x6dbe45ec, nil, nil, nil, nil, ".mmmm" },
  [1141] = { "La famiglia e la canna da pesca", "Pesca 6 Darkshore Grouper per Gubber Blump, ad Auberdine.", "Adoro pescare. La famiglia Blump è famosa per la pesca. Mi chiamo Gubber Blump; pesco.\n\nC'è un tipo di pesce che mi piace pescare da queste parti, si chiama Darkshore Grouper. Prima uscivo in barca a pescare cernie, ma non esce più nessuna barca da quando sono arrivati quei cattivoni dei murloc. Scommetto che si stanno mangiando anche tutte le cernie.\n\nSenti, mi aiuti a pescare Darkshore Grouper? Se lo fai ti darei una vera Blump Family Fishing Pole! È proprio una bella canna per pescare.", "Ci sono un sacco di buoni piatti che si fanno con le Darkshore groupers. Sono buone da mangiare, ma secondo me è più divertente pescarle.\n\nHai già preso qualche Darkshore grouper?", "Queste sì che sono belle groupers, {name}! Grazie per l'aiuto!\n\nSei <bravo/brava> a pescare almeno quanto mia cugina, Graun Blump. Ha anche la barba e un odore un po' strano, ma questo non le impedisce di pescare. Secondo me hai la stoffa per usare una Blump Family Fishing Pole.", 0x51cfab45, 0xde03fdb7, 0x220d149f, 0x9b959209, 0x5b8f085a, "....." },
  [1142] = { "La mortalità declina", "Trova il Treshala's Pendant e riportalo a Treshala Fallowbrook, a Darnassus.", "Non mi resta molto da vivere... così... così... debole.\n\n...il c-c-coraggioso nano, Lonebrow, è stato mandato ad a-a-avvertire Falfindel...\n\nMa prima che io... m-m-muoia...\n\n...mia moglie, Treshala... il suo ciondolo che ci legava... rubato... da uno di quei l-l-luridi aggressori...\n\nTrovalo, t-t-ti prego... e riportalo a Treshala, a Darnassus...\n\n...insieme alla n-n-notizia della mia morte... solitaria.", "Cosa ti porta a casa mia, {race}?", "No!\n\nNon è giusto. Oh, mondo crudele e insopportabile!\n\nOra devo portare questo fardello di dolore e non lasciare che il lavoro di Heralath muoia con lui.\n\nHai avuto coraggio a venire da un posto così pericoloso, {name}. Ma ti prego, ora lasciami.\n\nPiangerò in solitudine.", 0x2566ff32, 0xee06bc91, 0x7bd38ff5, 0x01d3203d, 0xd4c26cfb, "....." },
  [1143] = { "La Tower of Althalaxx", "Uccidi Athrikus Narassin e porta la sua testa a Balthule Shadowstrike, vicino alla Tower of Althalaxx.", "Capisco. Be', se quello che dici è vero, ora è il momento di colpire. Credo che Athrikus stia in cima alla torre. Ma stai <attento/attenta>: è circondato da molti stregoni potenti, molto più letali di quelli che hai affrontato prima.", "Athrikus Narassin è uno stregone antico e potente. Forse dovremmo attendere l'aiuto di Delgren, ma evidentemente aveva molta fiducia in te per mandarti da <solo/sola>.", "Con la morte di Athrikus, spero che le forze demoniache di questa zona vengano respinte. Non ho dubbi che si riorganizzeranno e torneranno, ma allora saremo ancora più preparati ad affrontare la loro minaccia.", 0x6dbe45ec, 0x0df455be, 0xb1924267, 0x1854f1fa, 0x2672806c, "....." },
  [1167] = { "La Tower of Althalaxx", nil, nil, nil, nil, 0x6dbe45ec, nil, nil, nil, nil, ".mmmm" },
  [1178] = { "Sponsorizzazione goblin", nil, nil, nil, nil, 0x3e5e1f8e, nil, nil, nil, nil, ".mmmm" },
  [1180] = { "Sponsorizzazione goblin", "Parla con il Wharfmaster Lozgil, a Booty Bay.", "Torniamo al motivo per cui sei qui. So di aver promesso a Pozzik che gli avrei consegnato un nuovo regolatore di carburante, ma non l'ho ancora ricevuto. Revilgaz, a Booty Bay, ha detto che l'avrebbe spedito, ma forse in qualche modo si è perso per strada.\n\nSe è così, non c'è molto che possiamo fare. Possiamo almeno scoprire se è stato spedito da Booty Bay.\n\nInformati presso il Wharfmaster Lozgil, laggiù: dovrebbe poter controllare i registri dei carichi.", nil, "Spedizioni per Ratchet? Lasciami controllare i registri...\n\nNo, la spedizione più recente per Ratchet che ho registrato sono stivali da Drizzlik. Non c'è stato molto altro, a parte materiali da costruzione e attrezzi. Di sicuro nessun pezzo da corsa.", 0x3e5e1f8e, 0x38005cbf, 0x3e7ecd8a, nil, 0x4f208c0b, "...m." },
  [1181] = { "Sponsorizzazione goblin", nil, nil, nil, nil, 0x3e5e1f8e, nil, nil, nil, nil, ".mmmm" },
  [1182] = { "Sponsorizzazione goblin", nil, nil, nil, nil, 0x3e5e1f8e, nil, nil, nil, nil, ".mmmm" },
  [1183] = { "Sponsorizzazione goblin", nil, nil, nil, nil, 0x3e5e1f8e, nil, nil, nil, nil, ".mmmm" },
  [1185] = { "Sotto la chitina c'era...", nil, nil, nil, "Ehi, sei di nuovo tu! Cioè, tu, nel senso del tu che è {name}! Sì, proprio quel tu!\n\nEhi, lasciami ricominciare!\n\nQuell'oggetto che hai trovato a Silithus era davvero un libro. Era un diario scritto in un dialetto antichissimo di la lingua che oggi chiamiamo Darnassian. Ci vorrà un po', ma lo esaminerò con estrema attenzione. Ho pensato che dovessi sapere che ciò che hai trovato era di enorme valore per il Circle.\n\nLa madre della tana è tutta emozionata!", 0xa4f443d7, nil, nil, nil, 0x3784d4d5, ".mmm." },
  [1198] = { "In cerca di Thaelrid", "Cerca Argent Guard Thaelrid nelle Blackfathom Deeps.", "In questi giorni girano molte voci sull'alleanza tra il Twilight's Hammer e i naga nelle Blackfathom Deeps, sulle coste di Ashenvale.\n\nIl mio ruolo qui con l'Argent Dawn è raccogliere più informazioni possibile, così da sapere quando e dove c'è bisogno di aiuto.\n\nSono settimane che ho mandato un esploratore a controllare l'attività nelle Blackfathom Deeps. Argent Guard Thaelrid non ha ancora fatto rapporto.\n\nGli altri miei esploratori sono impegnati in questioni urgenti.\n\nCerca Thaelrid e aiutalo da parte mia, {name}.", nil, "Dawnwatcher Shaedlass ha fatto bene a mandarti. In questo luogo corrotto è davvero in corso un complotto malvagio.", 0x6711bba5, 0x899a2616, 0x5e4d6659, nil, 0xa5cf35d8, "...m." },
  [1199] = { "Cade il crepuscolo", "Porta 10 Twilight Pendants ad Argent Guard Manados, a Darnassus.", "Forti degli antichi riti dei caotici Old Gods, i membri del Twilight's Hammer lottano per il ritorno dei loro oscuri patroni e per diffondere morte e terrore nel mondo.\n\nCrediamo che il Twilight's Hammer si sia alleato con i naga e si stia radunando nelle Blackfathom Deeps, sulla costa di Ashenvale.\n\nQualunque piano malvagio si stia preparando nelle profondità del vecchio tempio, va sventato.\n\nMuovi guerra all'Hammer e porta la prova delle tue azioni. I tuoi sforzi saranno ricompensati generosamente.", "Le Blackfathom Deeps un tempo erano un antico tempio degli elfi della notte. Custodivano un pozzo lunare potentissimo. Chissà quale male vi prepara ora il Twilight's Hammer.\n\nHai fatto progressi nel liberarcene?", "Hai senza dubbio sangue coraggioso e nobile, {name}. L'Argent Dawn ti loda per i tuoi sforzi contro il male.", 0x89671cf6, 0x4e205a89, 0x1b3033fd, 0x81e6c9bf, 0x80ee0d52, "....." },
  [1200] = { "Malvagità a Blackfathom", "Porta la testa di Twilight Lord Kelris a Dawnwatcher Selgorm, a Darnassus.", "Le forze mi hanno abbandonato. Ho bisogno del tuo aiuto!\n\nTanto tempo fa questo luogo era un grande tempio di Elune. Ma la sventura lo portò alla rovina quando la corruzione di un Old God salì da sotto la terra e contaminò il sacro Moon Well.\n\nAku'Mai, servitore dell'Old God, emerse dalle acque.\n\nI cultisti del Twilight's Hammer si sono alleati con i naga per occupare questi luoghi. I cultisti, guidati da Kelris, sacrificano innocenti ad Aku'Mai in cambio di potere.\n\nUccidi Kelris e porta la sua testa a Selgorm, a Darnassus, {name}, ti prego.", "Il tempo è un bene prezioso, {class}.\n\nIl mio ruolo qui a Darnassus è assicurare che l'Argent Dawn prosperi e che le forze del male che avanzano su Kalimdor vengano fermate.\n\nDi' in fretta cosa vuoi, o vai per la tua strada.", "Kelris ci sfuggiva da parecchio tempo.\n\nSembra che ogni volta che il male si faceva sentire da queste parti, Kelris ci avesse avuto una parte. Per un po' lo abbiamo creduto morto o disperso.\n\nMa ora tutto ha senso. Ponendo fine al suo dominio hai risparmiato la vita a molti innocenti.\n\nPer la Luce! Sacrificare qualcuno al servitore di un Old God per il proprio tornaconto è oltre ogni biasimo!\n\nHai compiuto una grande impresa, {name}. Ti rendo onore a nome dell'Argent Dawn.", 0x43ec82c9, 0x563f3e88, 0x7cceb3eb, 0xcf6bba07, 0xa9fa6819, "....." },
  [1220] = { nil, nil, nil, "Hai qualcosa per me?", nil, nil, nil, nil, 0xa03be4c2, nil, "mmm.m" },
  [1221] = { "Tuberi di Blueleaf", "Prendi una Crate with Holes.\n\nPrendi uno Snufflenose Command Stick.\n\nPrendi e leggi lo Snufflenose Owner's Manual.\n\nA Razorfen Kraul, usa la Crate with Holes per evocare uno Snufflenose Gopher e usa il Command Stick sul gopher per fargli cercare i tuberi.\n\nPorta 6 Blueleaf Tubers, lo Snufflenose Command Stick e la Crate with Holes a Mebok Mizzyrix, a Ratchet.", "I tuberi di blueleaf sono una prelibatezza in tutto il mondo! Ma sono rari, rarissimi. L'unico posto dove trovarli è qui nelle Barrens, nel profondo della terra, a Razorfen Kraul.\n\nE anche lì è impossibile trovarli se non sai esattamente dove cercare! Per questo ho addestrato questi gopher snufflenose a trovarli per me. Hanno un ottimo fiuto e sentono l'odore di un tubero a cinquanta passi.\n\nNon sarà facile, ma se mi porti dei tuberi ti pagherò profumatamente.", "Hai i tuberi, {name}?", "Ottimo, li hai presi! Posso venderli ai miei contatti a peso d'oro!\n\nGrazie per la consegna, {name}! Sei un ottimo socio.", 0x7ee65c2a, 0x7098b232, 0x604bd2e9, 0x6deb831e, 0xca3541f1, "....." },
  [1238] = { nil, nil, nil, "Hai qualcosa per me?", nil, nil, nil, nil, 0xa03be4c2, nil, "mmm.m" },
  [1241] = { "Il diplomatico scomparso", nil, nil, nil, nil, 0xbe525a75, nil, nil, nil, nil, ".mmmm" },
  [1242] = { "Il diplomatico scomparso", nil, nil, nil, nil, 0xbe525a75, nil, nil, nil, nil, ".mmmm" },
  [1243] = { "Il diplomatico scomparso", nil, nil, nil, nil, 0xbe525a75, nil, nil, nil, nil, ".mmmm" },
  [1244] = { "Il diplomatico scomparso", "Trova il Defias Docket e riportalo a Watcher Backus, a Duskwood.", "Attività dei Defias? Be', c'è sempre qualche attività: anche se se ne stanno per conto loro, li consideriamo una minaccia.\n\nMa ora che ci penso, c'è stato un avvistamento recente che mi è sembrato strano. Dev'essere stato un paio di settimane fa: alcuni dei loro agenti si erano radunati intorno all'Addle's Stead. Dal rapporto, avrei detto che stava succedendo qualcosa di grosso.\n\nPerché non vai a controllare lì e mi riporti quello che trovi?\n\nLa fattoria è a sud della strada che viene da Westfall, appena entri a Duskwood.", "Stai <attento/attenta> là fuori, {name}. So che ti ha mandato qui Trias, ma questo non vuol dire che nei boschi non ci sia in agguato qualcosa che possa darti dei guai... soprattutto ora che indaghi sui Defias.", "Sei <tornato/tornata> <sano/sana> e <salvo/salva>. Non si potrebbe chiedere di meglio, no?\n\nOra vediamo cos'abbiamo qui. Sembra piuttosto ufficiale, rispetto ai documenti dei Defias che ho visto. Ma potrebbe essere un trucco solo per sviarti da qualunque cosa tu stia cercando.", 0xbe525a75, 0x48feff50, 0xea67aecc, 0xcea0ed63, 0x67804e8a, "....." },
  [1245] = { "Il diplomatico scomparso", "Porta il Defias Docket a Elling Trias, a Stormwind.", "Accidenti, questo è troppo complicato per essere solo un modo per sviarti. Non dovrei nemmeno guardare questa roba. Portala a Trias: lui saprà capirci qualcosa. E non lasciare per nessun motivo che qualcuno ti ostacoli. È più grande di me. Forse è più grande persino di lui, ma vedremo.\n\nE fammi un favore, {name}: non dire a nessuno che ti ho aiutato. Se i miei superiori scoprissero che sapevo qualcosa di tutto questo e non gliel'ho detto, probabilmente mi impiccherebbero.", "Vedo che sei <tornato/tornata>, e tutto d'un pezzo. Sappiamo entrambi che non sei qui per il formaggio, quindi lasciamo perdere i convenevoli. Backus ti è stato d'aiuto, o non sei nemmeno <partito/partita> per Duskwood?", "Sì... questa è una lettura interessante. Jorgen e DeLavey hanno fatto bene a coinvolgermi.\n\nSembra che i Defias si siano dati parecchio da fare per portare a termine questo loro piano. Mmm... cos'è questo? \"Fist\"? È un nome che mi suona familiare.", 0xbe525a75, 0xa98e158b, 0xfafe092f, 0x24e86e52, 0x8bf38d0b, "....." },
  [1246] = { "Il diplomatico scomparso", nil, nil, nil, nil, 0xbe525a75, nil, nil, nil, nil, ".mmmm" },
  [1247] = { "Il diplomatico scomparso", "Parla con Elling Trias, a Stormwind.", nil, nil, nil, 0xbe525a75, 0x3f1c2d43, nil, nil, nil, "..mmm" },
  [1248] = { "Il diplomatico scomparso", nil, nil, nil, nil, 0xbe525a75, nil, nil, nil, nil, ".mmmm" },
  [1249] = { "Il diplomatico scomparso", nil, nil, nil, nil, 0xbe525a75, nil, nil, nil, nil, ".mmmm" },
  [1250] = { "Il diplomatico scomparso", nil, nil, nil, nil, 0xbe525a75, nil, nil, nil, nil, ".mmmm" },
  [1260] = { nil, "Parla con Morgan Stern, a Theramore.", "Sto preparando un nuovo menu per il ristorante. Sarà pieno di piatti rustici a tema \"bayou\". Credo che la mia clientela al Blue Recluse li adorerà!\n\nHo mandato mio nipote Morgan a Theramore, una città al margine del Dustwallow Marsh. È lì a raccogliere ricette dalla gente del posto, e devo sapere cosa ha trovato finora.\n\nIl viaggio fino a Theramore è lungo. Troppo lungo per me. Ma scommetto che qualcuno di giovane come te, {class}, coglierebbe al volo l'occasione di viaggiare, vero?", nil, "Oh, ti ha mandato mio zio, eh?\n\nBeh, ho fatto ricerche sulle ricette e ho qualche pista, ma mi serve aiuto.\n\nL'aiuto di qualcuno disposto a bagnarsi i piedi.", nil, 0xccbf98b5, 0x542d5629, nil, 0x3b4fc026, "m..m." },
  [1264] = { "Il diplomatico scomparso", nil, nil, nil, nil, 0xbe525a75, nil, nil, nil, nil, ".mmmm" },
  [1265] = { "Il diplomatico scomparso", nil, nil, "Sì, {name}?", nil, 0xbe525a75, nil, nil, 0xabfc0333, nil, ".mm.m" },
  [1266] = { "Il diplomatico scomparso", nil, nil, nil, nil, 0xbe525a75, nil, nil, nil, nil, ".mmmm" },
  [1267] = { "Il diplomatico scomparso", nil, nil, nil, nil, 0xbe525a75, nil, nil, nil, nil, ".mmmm" },
  [1271] = { "Banchetto al Blue Recluse", nil, nil, nil, "Mio nipote ha detto che l'hai aiutato con le sue ricerche a Dustwallow e che hai tirato fuori dai guai il suo socio. Beh, noi Stern restiamo uniti e non ignoriamo i nostri amici!\n\nQuindi lavati le mani, {name}, perché stiamo per dare una festa in tuo onore!", 0x68de3fd4, nil, nil, nil, 0x54293c24, ".mmm." },
  [1274] = { "Il diplomatico scomparso", nil, nil, nil, nil, 0xbe525a75, nil, nil, nil, nil, ".mmmm" },
  [1275] = { "Studiare la corruzione", "Gershala Nightwhisper, ad Auberdine, vuole 8 Corrupt Brain stems.", "Quegli sciocchi degli elfi del sangue si dannano con la magia demoniaca. Non hanno visto cos'è successo ai naga e ai satiri di Kalimdor?\n\nTemo che gli elfi del sangue andranno incontro a una deformazione simile. Azeroth non può permettersi che nasca un'altra razza immonda di mostri.\n\nVoglio studiare i tronchi cerebrali dei satiri e dei naga per capire verso quale destino si dirigono gli elfi. Nelle Blackfathom Deeps, sulla costa di Ashenvale, troverai sia satiri sia naga.\n\nÈ un lungo viaggio, {name}.", "Una volta che avrò abbastanza campioni da studiare, il mio vero lavoro potrà cominciare. Con i tronchi encefalici corrotti sia dei satiri sia dei naga di Blackfathom Deeps posso cercare una correlazione tra le mutazioni.\n\nForse, con le conoscenze acquisite, potremo impedire agli elfi del sangue di sprofondare ancora di più nella deformità e nel male.", "Hai viaggiato lontano e senza dubbio affrontato grandi pericoli.\n\nLe tue azioni sono state altruiste. È per il bene di tutta Azeroth che mi aiuti nelle mie ricerche. Ti ringrazio, {name}, per tutto ciò che hai fatto.\n\nOra, se vuoi scusarmi, ho molto lavoro da fare....", 0x80a39979, 0x1c3b6c70, 0x7deb66bd, 0x0e194d4e, 0x90492795, "....." },
  [1301] = { nil, "Parla con Vincent Hyal, a Menethil Harbor.", "Prima di lavorare qui al Blue Recluse, sono stato istruito da uno dei migliori cuochi e locandieri che abbia mai conosciuto. Si chiamava James Hyal. Tutto quello che ho e tutto quello che ho ottenuto nella vita lo devo a lui.\n\nChissà come sta. Lui e suo fratello Vincent sono andati a lavorare in una taverna a Menethil Harbor, ma ultimamente non ho sue notizie.\n\nSe mai ti capitasse di andare da quelle parti, potresti salutarlo da parte mia?", nil, "James? Oh, se n'è andato da un pezzo.\n\nGli è tornato il patriottismo, immagino. Non è difficile capire perché. Con tutta la follia a Lordaeron, molti si sono uniti a Jaina Proudmoore quando è partita oltre il mare.", nil, 0xc1cf5639, 0x894d2527, nil, 0xb47d985d, "m..m." },
  [1302] = { nil, "Parla con Clerk Lendry, a Theramore.", "Mio fratello James è partito oltre il mare con Lady Proudmoore. L'ultima volta che ho saputo qualcosa, laggiù i combattimenti si erano calmati e James stava aprendo una locanda da qualche parte nel continente. Ovunque sia, di sicuro fa buoni affari. Era un cuoco dannatamente bravo.\n\nÈ da un po' che non ho sue notizie, troppo preso dalla locanda, scommetto, ma l'impiegato di Theramore potrebbe probabilmente indicarti dove trovarlo.", nil, "James Hyal, James Hyal... Perché questo nome mi suona così familiare?\n\nMa certo! L'incidente dello Shady Rest Inn. Se hai informazioni su quello che è successo lì, ti consiglio vivamente di parlarne con Captain Vimes. È lui che si occupa dell'indagine.", nil, 0x1cc2fc0c, 0x228dd9c4, nil, 0x331f172f, "m..m." },
  [1324] = { "Il diplomatico scomparso", nil, nil, nil, nil, 0xbe525a75, nil, nil, nil, nil, ".mmmm" },
  [1338] = { "L'ordine di Stormpike", "Porta la Stormpike's Request a Furen Longbeard, a Stormwind.", "C'è un armaiolo nanico di cui ammiro molto il lavoro. Si chiama Furen Longbeard, e la sua abilità non ha pari. Mi serve un nuovo scudo, e devo averne uno dei suoi!\n\nIl problema è che... Furen è molto a sud, nel quartiere nanico di Stormwind. In terra umana! Non riesco a immaginare perché viva là, così lontano da Ironforge. Gli umani devono pagarlo come un re per tenerlo lì!\n\nAllora, se ti va di viaggiare e non ti dispiace guadagnare qualcosa, porteresti a Furen la mia richiesta per uno scudo?", "Una lettera dalle terre naniche? Chissà chi mi scrive da così lontano a nord...\n\nTi prego, fammi vedere l'ordine.", "Ah, una richiesta da uno degli Stormpike. È un clan fiero, pieno di nani di qualità. E ricchi, anche.\n\nGrazie, {name}. Mi metterò al lavoro sullo scudo di Mountaineer Stormpike entro la fine della giornata.", 0xecf988f4, 0x130880f5, 0x24e88b1f, 0xd07031a3, 0xae03cdbb, "....." },
  [1339] = { "L'incarico del Mountaineer Stormpike", "Parla con il Mountaineer Stormpike.", "Ho sentito che il Mountaineer Stormpike cerca un corriere. Qualcuno che faccia qualche viaggio per lui. Che ne dici? Sei la persona adatta, {race}?\n\nSe sì, troverai Stormpike in cima alla torre di guardia settentrionale.", nil, "Esatto. Ho un compito che non posso svolgere mentre sono di guardia. Anzi, ti porterà lontano da Loch Modan.\n\nLa tua occasione perfetta per l'avventura!", 0x7fce6abd, 0x1e66698f, 0xb2c24d7c, nil, 0x86e71667, "...m." },
  [1359] = { nil, nil, nil, "Hai qualcosa per me?", nil, nil, nil, nil, 0xa03be4c2, nil, "mmm.m" },
  [1363] = { "L'incarico di Mazen", "Parla con l'Acolyte Dellis, a Stormwind.", "Come custode delle opere di questa biblioteca dell'Academy of Arcane Arts and Sciences, è mia responsabilità assicurarmi che tutti i tomi e le pergamene magiche siano sempre al loro posto. Chissà quale follia si scatenerebbe se alcuni di questi testi incantati finissero nelle mani sbagliate?\n\nIl che mi ricorda... il mio assistente, Dellis, la settimana scorsa ha commesso un errore terribile. In biblioteca è piuttosto capace, ma è un incompetente quando esce dalle porte di Stormwind. Sii <un/una> <eroe/eroina> e aiuta il vecchio Dellis, ti va?", nil, "Non è stata colpa mia. Davvero, non lo è stata.", 0x9b7f1af7, 0xa52657ac, 0xc73b33de, nil, 0x4198d05d, "...m." },
  [1364] = { "L'incarico di Mazen", "Recupera i Khadgar's Essays on Dimensional Convergence e consegnali al Watcher Mahar Ba, a Nethergarde Keep.", "Le istruzioni del Master Mazen erano chiarissime: consegnare un saggio molto importante al Watcher Mahar Ba, a Nethergarde Keep.\n\nMa non ero mai stato nelle Blasted Lands! Il viaggio è stato spaventoso!\n\nQuando sono arrivato nello Swamp of Sorrows, ho sbagliato strada e mi sono ritrovato circondato da orribili creature palustri simili a piante. Barcollavano verso di me come per attaccarmi, così sono scappato. Ma nella fretta ho lasciato cadere il saggio. Sono sicuro che l'ha preso una di quelle bestie.\n\nPotresti per favore cercare di recuperarlo e consegnarlo a Mahar Ba?", "Cosa ti porta a Nethergarde Keep, {race}?", "Ah, splendido!\n\nPer un po' avevo temuto che la mia richiesta dei Khadgar's Essays on Dimensional Convergence fosse stata trascurata dal Master Mazen dell'Academy of Arcane Arts and Sciences.\n\nDev'essere sommerso di richieste, visti i tanti strani avvenimenti in corso.\n\nOra, se vuoi scusarmi, devo cominciare subito le mie ricerche. Poter finalmente scorgere l'intuizione di un grande come Khadgar mi emoziona oltre ogni dire.", 0x9b7f1af7, 0x92af49f7, 0xcc4a9ccb, 0x650cdeab, 0x6fe2a3a5, "....." },
  [1366] = { "Taglia sui centauri", nil, nil, nil, nil, 0x06d4a2f6, nil, nil, nil, nil, ".mmmm" },
  [1367] = { nil, "Ottieni la reputazione Friendly con i Magram, poi parla con Warug.", nil, nil, nil, nil, 0x7eb0b368, nil, nil, nil, "m.mmm" },
  [1368] = { nil, "Ottieni la reputazione Friendly con i Gelkis, poi parla con Uthek the Wise.", nil, nil, nil, nil, 0x51384a38, nil, nil, nil, "m.mmm" },
  [1369] = { nil, "Mantieni la tua reputazione con i Magram e porta 3 Broken Tears a Warug, al Magram Village.", "I Gelkis pensano che nostra madre dei centauri, Theradras, ci protegga. Sono stupidi. Nessuno protegge i centauri. I Magram non hanno bisogno di protezione! Noi siamo i più forti!\n\nMostra ai Gelkis che sono stupidi. Va' nella grotta del loro villaggio. In quella grotta accumulano cristalli, le lacrime di Theradras. Distruggi le lacrime e portami i pezzi rotti!", "Se non sei nostro nemico, farai ciò che ti chiedo!", "Hai preso le lacrime! Ora i Gelkis sapranno che Theradras non li aiuterà. Non piangerà quando li schiacceremo! I Magram regneranno!\n\nSei <furbo/furba> ad aiutarci, {name}. Noi siamo i più forti.", nil, 0xa72257e7, 0x67b6cf3a, 0x407b8c54, 0x72f06993, "m...." },
  [1370] = { "Rubare le provviste", "Porta 6 sacchi di Crudely Dried Meat a Uthek the Wise, al Gelkis Village.", "Quando non siamo in guerra, cacciamo per la carne. La carne ci dà forza, e le pance piene combattono meglio di quelle vuote.\n\nÈ lo stesso per i Magram. Conservano carne in più per poter combattere più a lungo tra una caccia e l'altra. Se fai razzia nel loro villaggio a est e prendi le loro scorte di carne, la loro forza verrà meno.", "Torna dopo aver dimostrato ancora il tuo valore ai Gelkis!", "Bene. Sento brontolare le pance dei Magram dal loro villaggio, lontano lontano!\n\nDarò questa carne ai Gelkis. E combatteremo per molti giorni senza riposo.\n\nCiò che hai fatto è un bene per i Gelkis, {name}.", 0x73f9471d, 0xfb323230, 0x2395d2b3, 0x8a2d6702, 0x83fe3f46, "....." },
  [1371] = { "Un aggeggio per Warug", "Mantieni la tua reputazione con i Magram e porta un Advanced Target Dummy a Warug, al Magram Village di Desolace.", "Tanto tempo fa, un piccolo gnomo venne a Desolace. Aveva cavalli e un carro, e il carro conteneva cose strane. Cose buffe. Cose che bruciavano di colori diversi. Cose che si muovevano e non erano vive. Ho ucciso il piccolo gnomo, ma prima... mi ha fatto ridere.\n\nHo tenuto la mia cosa preferita del suo carro. Era un umano fatto di legno e mi salutava con la mano finché non l'ho colpito e rotto.\n\nNe voglio uno nuovo. Portamene uno nuovo!", "Se non sei nostro nemico, farai ciò che ti chiedo!", "Sì, è proprio quello che avevo! Lo farò muovere di nuovo. Mi fa ridere!", 0x4f769b60, 0x2f21bf99, 0x54814c85, 0x407b8c54, 0xb8ff3b0f, "....." },
  [1373] = { nil, "Mantieni la tua reputazione con i Gelkis e porta un Draenethyst Shard a Uthek the Wise, al Gelkis Village di Desolace.", "Hai ancora molto da dimostrare, e il tuo prossimo compito ti porterà lontano, quindi per ora i Gelkis combatteranno i Magram senza di te.\n\nLa terra sussurra molti segreti a chi ascolta. Un segreto che sento è quello di un cristallo rosso. Si chiama draenethyst, ed è nuovo per la nostra terra. Viene da un luogo dove le montagne volano e dove regnano i demoni.\n\nPortami un frammento di draenethyst e renderà forte la mia magia! Il frammento si trova in un luogo chiamato Swamp of Sorrows, custodito dallo sperduto Ongeku.", "Mostrami che sei <amico/amica> dei Gelkis, {name}.", "Sì, questo è il frammento di cui sussurrava la terra. Sento in esso una magia forte! Userò questa magia contro i nemici dei Gelkis.\n\nHai svolto un altro compito per noi, {name}. Forse presto ti chiameremo <amico/amica>.", nil, 0x75042547, 0x76e99d01, 0x16b10c28, 0xe31475d3, "m...." },
  [1374] = { nil, "Porta la Khan Jehn's Head a Uthek the Wise, al Gelkis Village di Desolace.", "La terra mi parla, e dice che i Magram si indeboliscono. Ora è il momento di uccidere il loro Khan!\n\nPortami la testa del Khan dei Magram, Jehn!", "Mostrami che sei <amico/amica> dei Gelkis, {name}.", "Il Khan Jehn era forte, ma stupido. Pensava che la sua forza fosse grande. Non vedeva che la magia della terra è più forte. I centauri Magram ora cadranno senza il loro capo, e un giorno i Gelkis regneranno!", nil, 0xb931aa69, 0xb94a89cc, 0x16b10c28, 0xef98cf4e, "m...." },
  [1375] = { nil, "Mantieni la tua reputazione con i Magram e porta l'Head of Khan Shaka a Warug, al Magram Village di Desolace.", "Tu aiuti i Magram, e tu mi piaci. Ora uccidi il Khan dei Gelkis! È il Khan Shaka, e voglio la sua testa! Voglio fissare la sua testa e ridere di lui!", "Svolgi compiti per i Magram, e io ti aiuterò.", "Il Khan Shaka è morto! Metterò la sua testa su una picca e la terrò con me, così Shaka potrà vedere la forza dei Magram!", nil, 0xce816957, 0xe53d1b02, 0x0dc2136d, 0x18c5bcaf, "m...." },
  [1380] = { nil, "Mantieni la tua reputazione con i Gelkis e porta il Maraudine Key Fragment a Uthek the Wise, al Gelkis Village.", "{name}, ci hai aiutati contro i Magram. Ora aiutaci a battere i Maraudine! Uccidi il capo del loro clan, il Khan Hratha!\n\nPer affrontarlo, suona il Maraudine War Horn. Si trova in cima a un'alta rupe nella Valley of Spears.\n\nMa per suonare il corno devi procurarti un bocchino del corno da guerra. Sono rari, li portano solo i centauri Maraudine più fidati.\n\nDopo che il corno sarà suonato, arriveranno dei centauri. Uccidili finché non comparirà Hratha.\n\nIl Khan Hratha custodisce il pezzo di... una chiave. Portamelo...", "Il Khan Hratha è morto? Hai il frammento della chiave?", "È morto! Il Khan Hratha è morto! E ora cadranno i Maraudine! Quando i Gelkis regneranno su questa terra, {name}, ci ricorderemo di te. E gli spiriti della terra canteranno il tuo nome per sempre.", nil, 0x9642f60f, 0x6c401142, 0x1502ec7f, 0x462f6777, "m...." },
  [1381] = { nil, "Mantieni la tua reputazione con i Magram e porta il Maraudine Key Fragment a Warug, al Magram Village di Desolace.", "Il Khan dei Gelkis è morto, e ora cadranno i Maraudine! Uccidi il Khan dei Maraudine, Hratha!\n\nPer affrontarlo, suona il corno sull'alta rupe della Valley of Spears. Ma per suonare il corno ti serve un bocchino. Per avere un bocchino, uccidi i centauri Maraudine. Continua a uccidere finché non trovi un bocchino. Poi suona il corno.\n\nFallo e i centauri Maraudine verranno alla torre. Uccidili finché non comparirà il Khan Hratha. Hratha custodisce il pezzo di una chiave. Dammi quel pezzo...", "Fa' ciò che ti chiedo. Dimostrami che sei <alleato/alleata> dei Magram!", "Il Khan Hratha è morto! Ora i Magram sono i più forti dei centauri! Schiacceremo gli altri e regneremo su Desolace!\n\nCi ricorderemo di te, {name}, e i nostri zoccoli ti risparmieranno quando tutti gli altri saranno calpestati.", nil, 0x8191fcdf, 0x7ba3ffdb, 0xadd5101a, 0xf5be96ca, "m...." },
  [1382] = { "Una strana alleanza", "Ottieni la reputazione Friendly con i Gelkis, poi parla con Uthek the Wise.", "Siamo fortunati che i clan dei centauri combattano tra loro, perché se si unissero in un'unica forza sarebbero inarrestabili. Sì, siamo fortunati, e dovremmo sfruttare il nostro vantaggio.\n\nUno dei clan dei centauri, il clan Gelkis, è in guerra brutale con il clan Magram. Se attacchiamo i Magram, forse potremo stringere un'alleanza con i Gelkis.\n\nParla con Uthek the Wise, ai margini degli accampamenti Gelkis nel sud-ovest di Desolace. Attraverso di lei potremmo stringere un'alleanza con i Gelkis.", "Vattene! I Gelkis non ti vogliono qui. Vattene subito!!\n\nTorna dopo aver ucciso molti Magram, e allora parlerò con te.", "Il tuo nome viene sussurrato tra i Gelkis. Hai molto sangue Magram sulle mani. Questo è bene.\n\nForse è bene anche parlare. Parlare di cosa puoi fare per i Gelkis, e di cosa possiamo fare noi per te.", 0xee376413, 0x51384a38, 0x26257222, 0x05c7cbde, 0x04b86867, "....." },
  [1384] = { "Razzia contro i Kolkar", "Mantieni la tua reputazione con i Gelkis e porta 10 Crude Charms a Uthek the Wise, al Gelkis Village di Desolace.", "I centauri Kolkar pensano che la loro magia sia forte. Non conoscono la magia! Non la riconoscerebbero nemmeno se li mordesse!\n\nTu mostrerai loro che la loro magia è debole. Va' dai Kolkar a nord-est e uccidili. Prendi i loro amuleti. Portami gli amuleti e io li getterò nel fuoco e riderò!", "Hai gli amuleti? Hai mostrato ai Kolkar che sono deboli?", "Fai una cosa buona per i Gelkis. I Kolkar sono deboli e moriranno. La loro magia è patetica e non li salverà. Tu glielo hai mostrato, e la loro paura li renderà ancora più fiacchi!\n\nE nelle nostre terre, i fiacchi muoiono presto.", 0x0119bbcf, 0xb9787bfb, 0xa26a18c9, 0x0e2b206f, 0x817c7bc1, "....." },
  [1385] = { "Politica brutale", "Ottieni la reputazione Friendly con i Magram, poi parla con Warug.", "Desolace è una terra in guerra. I centauri si fanno guerra tra loro, e crediamo che il vincitore dilagherà e minaccerà le nostre roccaforti. Questo non possiamo permetterlo\n\nDobbiamo imparare a battere i centauri, e per farlo... dobbiamo allearci con uno dei clan. I centauri Magram sono in guerra con i Gelkis. Se combatti i Gelkis, i Magram potrebbero considerare un'alleanza.\n\nGuadagnati il favore dei Magram, poi parla con Warug, al villaggio Magram nel sud-est di Desolace.", "Ora te ne andrai, o i Magram ti schiacceranno! Per esserci <amico/amica>, devi uccidere i Gelkis.", "Molti Gelkis cadono per mano tua. Questo mi piace. Forse puoi fare altre cose che mi piacciono. Forse tu e i Magram potete essere amici.", 0x172c2704, 0x7eb0b368, 0xeb8642ad, 0xeb771986, 0x3a57bd89, "....." },
  [1386] = { "Assalto ai Kolkar", "Mantieni la tua reputazione con i Magram. Uccidi 12 Kolkar Centaur, 12 Kolkar Scout e 6 Kolkar Mauler, poi torna da Warug, al Magram Village di Desolace.", "I Kolkar pensano di essere forti, ma noi ridiamo di loro! Ridiamo e li uccidiamo! Uccidili anche tu. Mostrami che sai uccidere i Kolkar come noi. Va' a nord e uccidili tutti!", "Hai paura dei Kolkar? Perché non li uccidi? Forse hai dimenticato come si uccide. Sbrigati e uccidi i Kolkar prima che siano morti!", "Ora i Kolkar hanno paura di te! Spero che tu abbia riso mentre li uccidevi. È meglio ridere quando uccidi, così il nemico vede che è debole.", 0xbbc50e78, 0x52589a80, 0x89bc84c9, 0x37df1713, 0x749da75d, "....." },
  [1387] = { "Taglia sui centauri", "Porta 15 Centaur Ears al Corporal Melkins, a Nijel's Point, Desolace.", "Molti clan compongono la razza dei centauri. Ognuno ha il proprio capo e i propri scopi, ma tutti i clan hanno una cosa in comune. La crudeltà.\n\nSe mai vogliamo trovare la pace, i centauri devono essere eliminati. E così ti affido proprio questo compito.\n\nMentre vaghi per Desolace, dai la caccia ai centauri e prendi le loro orecchie. Portamene tante, tantissime.\n\nFallo al servizio dell'Alliance, {name}, e saremo un passo più vicini alla fine della guerra.", "Hai un rapporto, {name}?", "Ah, le orecchie. Ben fatto.\n\nIl tuo servizio all'Alliance è fuori discussione, {name}. Il sangue che hai versato a Desolace salverà senza dubbio innumerevoli vite.", 0x06d4a2f6, 0x8dc6c474, 0x780fd268, 0xe6610dc1, 0xc3517793, "....." },
  [1395] = { "Rifornimenti per Nethergarde", "Porta la Crate of Powerstones a Quartermaster Lungertz prima che le powerstone si esauriscano.", "Questa cassa di powerstone deve arrivare alla Nethergarde Keep, nelle Blasted Lands. Non manterranno a lungo il loro potere, quindi non possiamo spedirle con la prossima carovana.\n\nDevi portarle tu, e devi portarle in fretta.\n\nPortale a Quartermaster Lungertz, alla Nethergarde Keep. Per raggiungere la fortezza devi viaggiare verso est attraverso il Deadwind Pass, poi verso est attraverso la Swamp of Sorrows, poi verso sud attraverso le Blasted Lands.\n\nFai attenzione, {name}. Attraverserai terre pericolose, eppure non devi fallire.", "Salve! Non badare a tutto questo trambusto, è la solita routine alla Nethergarde Keep.\n\nHai qualcosa per me?", "Ah, le powerstone! I maghi saranno felici di vederle!\n\nMille grazie, {name}. So che il viaggio da Darkshire non è stato facile.", 0xa26e9783, 0x6e0883b5, 0x5e29a42b, 0x59251ed0, 0x8d183396, "....." },
  [1423] = { nil, nil, nil, "Hai qualcosa per me?", nil, nil, nil, nil, 0xa03be4c2, nil, "mmm.m" },
  [1437] = { "La ricerca di Vahlarriel", "Trova e perquisisci il carro di Tyranis e Dalinda Malem, a Desolace.", "Sono Vahlarriel, {name}. Sono venuta qui per scoprire dove si trovano due nobili scomparsi di una famiglia Darnassian di mercanti: la House Malem. Il padre della casata teme il peggio, e io devo fare tutto il possibile per ritrovare i suoi figli scomparsi. Non ho ancora cominciato a cercare Tyranis o Dalinda, ma spero di non dover restare qui a lungo.\n\nLe ultime notizie dicono che sono passati per le Stonetalon Mountains qualche settimana fa.\n\nSe trovi il loro carro, ti prego, vieni subito da me.", nil, "Frugando tra i resti del carro, diventa evidente che è stato attaccato sia con incantesimi sia con armi. La battaglia sembra essere stata impari e rapida; non c'è traccia di sangue, né resti di corpi.\n\nChiunque abbia attaccato il carro è stato efficiente e veloce.", 0x7ca9c473, 0x2f1bef36, 0x1e29426b, nil, 0x3b1107b1, "...m." },
  [1438] = { "La ricerca di Vahlarriel", "Trova Dalinda Malem a Desolace.", "Trova sia Dalinda sia Tyranis, se puoi, e torna da me con ciò che hai scoperto. Comincia la ricerca da questa fortezza. Contatterò subito i miei superiori a Darnassus e li informerò della situazione.\n\n{name}, c'è un'altra cosa che voglio sottolinearti. I miei superiori hanno mostrato una certa preoccupazione per Tyranis e i motivi che l'hanno portato qui. Per loro è più importante che Dalinda venga trovata e riportata indietro sana e salva. Tyranis deve essere... valutato prima di essere riportato a casa.", nil, "Sia ringraziata Elune, finalmente qualcuno è venuto ad aiutarmi. Ti prego, {class}, ho bisogno del tuo aiuto. Mio fratello Tyranis e io siamo stati catturati e portati qui dalla Burning Blade. Credo che vogliano sacrificarmi ai loro padroni demoniaci!\n\nSapevo che venire a Desolace era un errore, ma di recente Tyranis ha cominciato a bramare la conoscenza di tutto ciò che è arcano, anche contro il volere della nostra gente. Ha deciso di fare questo viaggio anche dopo aver sentito i racconti sull'infestazione demoniaca di questa terra.\n\nTemo il peggio per lui.", 0x7ca9c473, 0xe829ed7f, 0x2400811d, nil, 0x800a2c6a, "...m." },
  [1439] = { "Alla ricerca di Tyranis", "Trova Tyranis Malem a Desolace.", "Ci hanno portati qui dopo che gli orchi hanno massacrato tutte le nostre guardie e i nostri servitori. Oh, le cose terribili che hanno fatto loro! Pensavo che ci avrebbero uccisi lì per lì, ma è diventato chiaro che avevano altri piani.\n\nTyranis ha cercato di parlare con loro. Credo volesse impressionarli con la sua conoscenza dell'arcano... non so perché.\n\nTi prego, non posso andarmene da qui finché non so cosa è successo a mio fratello. Trovalo, poi torna a prendermi quando si conoscerà la sua sorte.", "Temo che Tyranis cercherà di apprendere i segreti della Burning Blade e di unirsi a loro, se glielo permetteranno: ha sempre adorato il potere che la magia dona a chi ne è sedotto.\n\nNon so se sopporterei di tornare a casa dalla mia famiglia con la notizia che lo spirito di Tyranis flirta con simili pericoli. Tra la mia gente è già un crimine abbastanza terribile perseguire cose del genere, ma diventare ciò da cui cerchiamo di proteggerci, beh, è riprovevole.", "È terribile! Ma immagino fosse necessario. Se non fosse stato per mano tua, di sicuro sarebbe stato per mano della mia gente. Immagino di doverti ringraziare: perdonami se non sembro sincera. Non intendo offenderti.\n\nOra che conosco la sorte di mio fratello, sembra giunto il momento della mia fuga. Se sei ancora <disposto/disposta>, accetterò il tuo aiuto per fuggire da questo luogo orribile.\n\nQuando sarai <pronto/pronta>, potremo metterci in salvo.", 0xbdd7dd05, 0xe08cffee, 0x4ef69f49, 0xe2f9a2df, 0xc8605933, "....." },
  [1440] = { "Ritorno da Vahlarriel", "Scorta Dalinda Malem fuori dalla Thunder Axe Fortress, poi torna da Vahlarriel Demonslayer, a Desolace.", "Quindi è il momento? Apprezzo i tuoi sforzi, e se la situazione non lo permettesse, lascia che ti ringrazi ora per tutto ciò che hai fatto per me e per la mia famiglia. Se sei <pronto/pronta>, non c'è altro per me qui: possiamo partire quando ritieni sia il momento giusto.", nil, "Grazie, {name}. Dalinda è tornata sana e salva qui a Nijel's Point, e in condizioni molto migliori di quanto potessi sperare. Il fatto che sia arrivata qui con le sue forze è un buon segno. Spero che tu stia bene?\n\nMi addolora sapere che non sono tornati sia Tyranis sia Dalinda, ma l'imbarazzo per le decisioni di Tyranis è suo da sopportare. È qualcosa che dovrà affrontare quando tornerà a Darnassus.", 0xbc22c5c2, 0x9d8532db, 0xf6f3ea86, nil, 0xdf942d1f, "...m." },
  [1442] = { "In cerca della Kor Gem", "Porta una Kor Gem a Thundris Windweaver, a Darkshore.", "Salute, {name}. Cosa posso fare per chi segue una via sacra?\n\nAh, sì, Stilwell, il fabbro... di tanto tempo fa. Lo ricordo bene, anche se non sento il suo nome da parecchio.\n\nNon mi è mai sembrato un uomo sfrontato, quindi posso solo pensare che il suo desiderio di una Kor Gem sia nobile.\n\nSe vuoi davvero una di quelle gemme, devi andare nella parte nord-occidentale di Ashenvale. Lì troverai le Blackfathom Deeps, tra alcune rovine antiche. I naga che usano ancora le gemme sono laggiù. Non andarci da <solo/sola>, {class}.", "Sarei meno fiducioso verso chi non segue un sentiero sacro, se venisse a chiedermi di una gemma Kor. Ma mi fido più della tua gente che di alcuni dei miei simili. Non giudico il tuo intero ordine in base alle azioni di un solo membro caduto.", "Questa è proprio la gemma che Stilwell desidera, ma prima di permetterti di portargliela devo purificarla dalla corruzione: è vero che le megere naga infondono potere nelle gemme, ma del loro genere malvagio.\n\nFai sapere a Stilwell che il suo potere è intatto e che dovrebbe funzionare bene per qualunque rituale desideri compiere.\n\nSpero tu sappia quel che fai, {class}: non è un oggetto da poco quello che possiedi.", 0x5d353131, 0x049bb428, 0x8e41ca81, 0x45d628b2, 0x4ca4aaaa, "....." },
  [1447] = { "Il diplomatico scomparso", nil, nil, nil, nil, 0xbe525a75, nil, nil, nil, nil, ".mmmm" },
  [1448] = { "Alla ricerca del tempio", "Brohann Caskbelly, a Stormwind, vuole che tu cerchi il Temple of Atal'Hakkar.", "C'è stato un tempo in cui ero giovane e pieno di vigore, come te, {class}.\n\nMa ora sono vecchio e non posso più esplorare il mondo come un tempo. Ah, le cose che ho visto!\n\nMa c'è stato un mistero che mi è sfuggito. Per la mia ultima missione, l'Explorers' League mi mandò alla ricerca del Temple of Atal'Hakkar. Si diceva che si trovasse nello Swamp of Sorrows.\n\nA causa delle mie condizioni fragili, l'ho cercato in volo su un grifone, ma non l'ho mai trovato.\n\nAiuteresti un vecchio nano? Forse a piedi avrai più fortuna.", "Ho viaggiato per il mondo, dalle giungle di Azeroth alle vette innevate di Khaz Modan.\n\nMai prima d'ora ho chiesto aiuto nelle mie avventure. Ma le mie vecchie ossa sono stanche.\n\nNulla mi darebbe più soddisfazione che sapere di aver completato la mia ultima missione per l'Explorers' League\n\nSe fossi così gentile da aiutarmi a cercare il Temple of Atal'Hakkar, {class}, te ne sarei molto grato.\n\nSetaccia lo Swamp of Sorrows e torna a riferirmi ciò che trovi!", "Il Temple of Atal'Hakkar è sprofondato sotto la Pool of Tears? E circondato dallo stormo dei draghi verdi?\n\nUna scoperta straordinaria, {class}. Ma evidentemente qualcosa è andato terribilmente storto.", 0xf54b5fd9, 0x1d48ee51, 0x73052453, 0xde93f335, 0xe5b8eafa, "....." },
  [1449] = { "Verso le Hinterlands", "Parla con l'High Thane Falstad Wildhammer all'Aerie Peak, nelle Hinterlands.", "Come ho detto prima, ho cercato di esplorare il tempio da solo, dall'alto. Beh, non ero proprio solo.\n\nSono andato alla famosa voliera di grifoni dell'Aerie Peak, nelle Hinterlands. Lì ho chiesto l'aiuto di uno dei loro migliori piloti. Il pilota è caduto dalla sua cavalcatura, giù nella palude...\n\nAlla mia età il nome di quel poveretto mi sfugge. Il maestro della voliera se lo ricorderà, di sicuro.\n\nVa' lì e cerca Falstad Wildhammer.\n\nDobbiamo scoprire cosa è successo a quel pilota.", nil, "Che vuoi, <ragazzino/signorina>? Non vedi che ho dei problemi da risolvere qui? Chi ha tempo di stare a chiacchierare con un chiacchierone della razza {race}?\n\nSpuntano troll da tutte le parti! Sbrigati.", 0xd0cc34a2, 0xb97cf5c4, 0x7af0d9ca, nil, 0xeb2412a7, "...m.", nil, nil, nil, nil, 0x750ec02a },
  [1454] = { "Il relitto di Karnitol", "Trova il Karnitol's Chest a Desolace.", "Il mio primo incarico è per il mago Karnitol, una specie di nobile di Stormwind. Pare che la sua nave sia stata attaccata da giganti marini al largo della costa nord-occidentale di Desolace. Lui e i suoi servitori hanno cercato di portare a riva uno dei suoi forzieri più preziosi, ma quando i giganti marini hanno attaccato in massa ha scelto di abbandonarlo e di teletrasportare se stesso e i suoi servitori in salvo.\n\nVuole che troviamo il forziere e il suo contenuto e glielo riportiamo a Stormwind.", nil, "Noti che il forziere non sembra avere danni causati dall'acqua.\n\nLa seconda cosa che noti è che il coperchio è stato forzato, e qualunque trappola magica fosse stata predisposta per proteggerlo è scattata da tempo: lo si capisce chiaramente dai segni di bruciatura lungo i bordi.", 0x77004981, 0x054562b5, 0x7adbdbf2, nil, 0x4cc9f50a, "...m." },
  [1455] = { "Il relitto di Karnitol", "Torna da Kreldig Ungor, a Desolace.", "Ti prendi qualche istante per capire cosa abbia forzato il forziere, e noti lungo i lati e sul coperchio graffi lunghi e profondi che rivelano che qualcosa di diverso da un uomo o da un gigante se ne è interessato. I segni non sembrano causati da un pugnale o da una spada.\n\nFrugando nel forziere, lo trovi completamente vuoto.\n\nNon avendo altro da fare, chiudi il forziere e ti prepari ad andartene. Kreldig sarà deluso.", nil, "<Bentornato/Bentornata> a Nijel's Point, {name}. Allora, dimmi cosa hai trovato.\n\nCosa!? Niente? Un forziere vuoto non ci farà pagare, temo.\n\nDimmi di più su quei segni che hai visto... quei graffi.", 0x77004981, 0x0438e587, 0x40c594a7, nil, 0xab30987a, "...m." },
  [1456] = { "Il relitto di Karnitol", "Trova la Karnitol's Satchel e riportala a Kreldig Ungor, a Desolace.", "Intrigante.\n\nBeh, forse non è ancora detta l'ultima parola.\n\nLungo quella stessa costa, ma più a nord, vicino alla Ranazjar Isle, ci sono rovine degli elfi della notte sul fondo dell'oceano. Una tribù di naga, gli Slitherblade, vive lì. Credo che sia la nostra possibilità migliore.\n\nSe un gruppo di esploratori si è spinto così a sud, doveva essere piuttosto potente. Se vuoi trovare gli effetti di Karnitol, comincerei dai naga più potenti: i tidehunter o le sea witch.", "Senza offesa per chiunque sia questo Nijel, ma questo accampamento non è il posto più comodo in cui abbia passato la notte, se capisci cosa intendo, {name}.", "Ottimo, {name}! Hai trovato gli effetti di Karnitol!\n\nQuei maledetti naga, sempre a creare guai. Credo che preferirei passare la vita in guerra con l'Horde piuttosto che dover affrontare la loro specie. Hai reso un grande servizio ai Reclaimers.", 0x77004981, 0x03a28634, 0x8eb022f8, 0xe6bee56f, 0x27c447b7, "....." },
  [1457] = { "Il relitto di Karnitol", "Porta la Karnitol's Satchel a Roetten Stonehammer, a Ironforge.", "Riporta le cose di Karnitol a Roetten, a Ironforge, e ti pagherà per un lavoro ben fatto.\n\nAhah, se non stai <attento/attenta>, sarà così contento di te che ti chiederà di unirti a noi a tempo pieno.\n\nAncora, ottimo lavoro, {name}.\n\nFa' attenzione sulla via del ritorno, e non metterci troppo: Karnitol non è il più paziente degli uomini, ma è comunque molto generoso.", "Gli affari vanno a gonfie vele, {name}, e non ho molto tempo per le domande. Se hai affari con i Reclaimers, sentiamo. Altrimenti dovrò chiederti di parlare con uno dei miei sottoposti: sono abbastanza bravi a occuparsi delle cose da queste parti.", "Ah, l'affare Karnitol a Desolace. Eccellente!\n\nQuindi il forziere è stato distrutto, ma gli oggetti ci sono tutti, eh? Beh, lascerò che sia lui a giudicare. Una cosa buona di questo mio affare è che se non sono soddisfatti posso mandarli a quel paese! Si affidano a noi per trovare la loro roba... non per assicurarci che sia tutta bella e in buono stato quando la riavranno.\n\nBel lavoro, {name}. Vediamo di farti pagare.", 0x77004981, 0x5d5a35d4, 0x939e2e91, 0x52455200, 0x731ac734, "....." },
  [1458] = { "Reagenti per la Reclaimers Inc.", "Porta 10 Hatefury Claws e 10 Hatefury Horns a Kreldig Ungor, a Desolace.", "Uno dei miei compiti qui consiste nel raccogliere alcuni reagenti per Leftwitch, un mago gnomo di Kharanos. Roetten pensa che siano soldi facili, visto che siamo già qui. Non gli importa granché che siamo già a corto di personale.\n\nLe prime cose della sua lista dovrebbero essere abbastanza facili da procurare, e chiunque mi aiuti guadagnerebbe un bel gruzzolo.\n\nMi servono corna e artigli dei satiri Hatefury, a est di qui. Riportameli e passeremo al resto della lista.", "Creature spregevoli, i satiri. Si dice che siano in qualche modo legati agli elfi della notte, ma non sono sicuro di crederci.\n\nCredo che si dica così per via di quell'elfo che li ha portati nella guerra qualche anno fa. Il mondo non è più stato lo stesso da allora. Molto più pericoloso, e molto più spaventoso.", "Bene bene, {name}. Non so se siano di buona qualità, ma se Leftwitch voleva un tipo specifico avrebbe dovuto specificarlo prima di mandare qui i Reclaimers.\n\nChe ne dici di passare al prossimo oggetto della sua lista?", 0xe45ccdc7, 0x0711f6fa, 0x57a7170f, 0x099adac5, 0x85c4b847, "....." },
  [1459] = { "Reagenti per la Reclaimers Inc.", "Porta 7 fiale di Scorpashi Venom e 3 Aged Kodo Hides a Kreldig Ungor, a Desolace.", "Il prossimo sulla lista di Leftwitch è... vediamo... mmm. Oh, eccolo.\n\nAbbastanza semplice, ma le sue indicazioni sono molto precise. Gli serve veleno di scorpashi e pelle di kodo. Le clausole in piccolo dicono che entrambi devono venire da creature specifiche: il veleno da uno qualsiasi degli scorpashi, e la pelle da un kodo anziano, non da quelli morenti o antichi.\n\nI maghi, te lo dico io, certe cose che vogliono... sono proprio strane.", "Scusa se non ho saputo dirti dove trovare i kodo o gli scorpashi. Non conosco molto bene la zona e non ho avuto tempo di esplorarla.", "Il tuo aiuto qui è una benedizione, {name}. Stai riducendo il tempo che passo a Desolace almeno della metà. Con il tuo aiuto tornerò a Ironforge a scaldarmi i piedi in un attimo.\n\nQuando avremo finito con questa lista e sarò tornato a casa, vienimi a cercare: ti offrirò di sicuro una birra.\n\nMa fino ad allora, raccogliamo il resto di questi reagenti.", 0xe45ccdc7, 0x223f4b46, 0x2e8f8320, 0xa6c85e6f, 0x29a4da1f, "....." },
  [1465] = { "La ricerca di Vahlarriel", "Riporta il Malem Pendant a Vahlarriel Demonslayer, a Desolace.", "Continuando a perquisire il carro, trovi non solo un pendente, ma anche delle impronte che si dirigono verso sud. In lontananza vedi del fumo salire da un grande forte. È il fumo di un fuoco curato, non di edifici in fiamme, e il tuo istinto ti dice che i Malem, se ancora vivi, sono stati portati in quella direzione.\n\nPensi che Vahlarriel, a Nijel's Point, debba non solo vedere il pendente che hai trovato, ma anche sapere dei segni di vita a sud.", nil, "Esasperante! Tutto questo disastro!\n\nErano stati avvertiti tutti e due di quanto fosse pericoloso venire qui. Ora sono entrambi scomparsi... o peggio.\n\nHai detto di aver visto delle tracce dirette a un forte qui vicino? Potrebbe essere la nostra possibilità migliore.\n\nDa quel che dice la gente del posto, quella fortezza è infestata da membri della Burning Blade, orchi che si sono votati alle cause dei demoni. Forse non rappresentano le convinzioni della maggior parte dell'Horde, ma sono malvagi e ti uccideranno a vista se ti sorprendono a spiare.", 0x7ca9c473, 0x2a425383, 0x27905566, nil, 0x24532a73, "...m." },
  [1466] = { "Reagenti per la Reclaimers Inc.", "Porta 10 Felhound Brains, 10 Nether Wings e 10 fiale di Doomwarder Blood a Kreldig Ungor, a Desolace.", "Questo è l'ultimo degli oggetti e, non ti mentirò, non è un bello spettacolo. Mi aspetto anche che ti ci vorrà un po' più di tempo che per gli altri.\n\nBasta avvertimenti, cominciamo. Leftwitch dice che gli servono: dieci cervelli di mana eater, mage hunter o ley hunter. Dieci nether wing di una nether maiden, sister o sorceress. E... dieci fiale di sangue di doomwarder da un doomwarder captain o lord.\n\nAbbastanza semplice, eh? Accidenti... se vuoi rinunciare a questo, ti capirei.", "Non sapevo nemmeno che queste cose demoniache fossero a Desolace. L'ultima volta che ho letto qualcosa, i centauri erano praticamente i padroni di queste terre dopo che gli elfi della notte se ne erano andati anni fa.\n\nMi chiedo perché si siano stabiliti qui, e come.", "Sinceramente? Non l'avrei mai detto. Sei <straordinario/straordinaria>, {name}. Affrontare demoni per gli esperimenti di un mago, e tornare pure <tutto/tutta> intero. Ottimo lavoro!\n\nParlerò di te a Roetten personalmente quando tornerò a Ironforge.", 0xe45ccdc7, 0x5b7fabfe, 0x3b351b55, 0xe2c29f34, 0x1036a532, "....." },
  [1467] = { "Reagenti per la Reclaimers Inc.", "Riporta il Leftwitch's Package a Roetten Stonehammer, a Ironforge.", "Per farti pagare dovrai tornare a Ironforge e parlare con Roetten in persona. Sarà comunque felice di togliersi di torno il pacco di Leftwitch. Dagli solo questo e dovrebbe bastare per avere il tuo bottino.\n\nE non preoccuparti, metterò comunque una buona parola per te quando tornerò. Non dovrei restare a Desolace ancora per molto.", "Ben <trovato/trovata>, {name}. Gli affari vanno a gonfie vele, il suono delle incudini risuona in tutta Ironforge, i mantici soffiano sui fuochi roventi e mia moglie mi sta preparando una torta per dessert dopo la cena di stasera. Potrebbe la vita essere più bella?", "Ah, il pacco per Leftwitch da Desolace. Eccellente. Apprezzo il lavoro e la tua puntualità, {class}. Felice di averti con noi almeno per questo piccolo lavoro.\n\nHo il tuo pagamento proprio qui. Che si sappia che la Reclaimers Inc. paga sempre bene una dura settimana di lavoro.", 0xe45ccdc7, 0xda6fadc1, 0xa74df9be, 0x305a2aa8, 0x0f265115, "....." },
  [1471] = { "Il vincolo", nil, nil, nil, nil, 0x5926988f, nil, nil, nil, nil, ".mmmm" },
  [1472] = { "Il divoratore di anime", nil, nil, nil, nil, 0xc90e9da6, nil, nil, nil, nil, ".mmmm" },
  [1474] = { "Il vincolo", nil, nil, nil, nil, 0x5926988f, nil, nil, nil, nil, ".mmmm" },
  [1475] = { "Nel Temple of Atal'Hakkar", "Raccogli 10 Atal'ai Tablets per Brohann Caskbelly, a Stormwind.", "Secondo la leggenda, il Temple of Atal'Hakkar è un santuario sacro dedicato all'antico dio Hakkar the Soulflayer. Custodito da una feroce tribù di troll chiamata Atal'ai, si dice che il tempio sia inespugnabile.\n\nOra che è sprofondato sotto la Pool of Tears, recuperare manufatti dal tempio è ancora più difficile. Ma è proprio quello che ho bisogno che tu faccia, {name}.\n\nAiutami raccogliendo le Atal'ai Tablets intatte. Portamele e tornerò all'Explorers' Guild da eroe. Condivideremo la gloria insieme.", "Mentre il crepuscolo scende lentamente sulla mia carriera, mi rivolgo a te, {name}, perché tu mi aiuti nella mia ultima missione per l'Explorers' League. Se le mie vecchie ossa trovassero la forza di sfidare lo Swamp of Sorrows e il tempio sommerso, combatterei proprio al tuo fianco.\n\nL'orgoglio mi rende difficile chiederti aiuto per raccogliere le Atal'ai Tablets. Ma la vecchiaia lo rende necessario.\n\nTi prego, aiutami, {name}. Voglio ritirarmi dall'Explorers' League dopo aver portato a termine il loro ultimo incarico.", "Le Atal'ai Tablets! Grazie, {name}!\n\nUna volta consegnate all'Explorers' League, i nostri nomi passeranno insieme alla storia. Hai aiutato un vecchio nano a compiere il suo ultimo dovere nella vita. Per questo ti sono eternamente grato.", 0xa403bf55, 0x7f6d6719, 0x09e59f8e, 0xa14e8aae, 0x4584ecfd, "....." },
  [1477] = { "Rifornimenti vitali", "Parla con il Watchmaster Sorigal.", "I nostri maghi stanno conducendo ricerche a Nethergarde Keep, nelle Blasted Lands, ricerche vitali per la nostra comprensione dei Dark Portal. Hanno bisogno di rifornimenti quasi continui, ma la nostra linea di rifornimento per Nethergarde è fragile.\n\nDevi aiutarci a far arrivare i rifornimenti a Nethergard. Presentati al Watchmaster Sorigal, a Darkshire, e fa' ciò che ti chiede. Questo compito ti porterà in terre ostili, {name}. Preparati.", nil, "Ti ha mandato Andromath? Molto bene. Ho un compito importante per te...", 0x9d8ff76c, 0x71a7d15d, 0x3ad8891c, nil, 0x84281d45, "...m." },
  [1483] = { nil, "Parla con Ziz Fizziks, a Windshear Crag.", "La Venture Company ha rubato molte delle migliori menti goblin, ma di tanto in tanto abbiamo l'occasione di rubarne qualcuna indietro.\n\nTempo fa, la squadra della Venture Company nelle Stonetalon Mountains ha assunto Gerenzo Wrenchwhistle: uno gnomo! L'altro loro ingegnere, Ziz Fizziks, ne è rimasto così sconcertato che mi ha supplicato di trovargli un nuovo impiego nella Tinkers' Union. Gli ho affidato qualche compito, ma potrebbe aver bisogno di aiuto.\n\nForse potresti andare a vedere come se la cava, per me? È di stanza al margine occidentale di Windshear Crag.", nil, "Pensavo che i capi della Venture Company fossero negrieri, ma poi ho conosciuto Sputtervalve, il più crudele di tutti!\n\nAh! Comunque è meglio che restare senza lavoro, immagino... O peggio, lavorare con quel Gerenzo. Se sei qui per aiutare, ho qualcosa da farti fare.", nil, 0xd85f0063, 0x5c119beb, nil, 0x4bc25ea8, "m..m." },
  [1486] = { "Pelli deviate", "Nalpak, nelle Wailing Caverns, vuole 20 Deviate Hides.", "Mentre Naralex sprofondava sempre più nel suo incubo, una strana razza di bestie è emersa da sotto le Barrens nelle Wailing Caverns.\n\nQueste creature deviate hanno proprietà strane, ultraterrene. Anche se di natura malvagia, secondo me dalla loro esistenza qui a Kalimdor può venire qualcosa di buono. Credo che le loro pelli saranno particolarmente utili nella lavorazione del cuoio.\n\nSe te la senti, avventurati nelle grotte sottostanti e recupera qualche pelle deviata.", "Sono molto interessato a esaminare le pelli delle creature deviate che hanno infestato queste grotte. Hai avuto fortuna a raccoglierne qualcuna, {class}?", "I tuoi sforzi nel raccogliere queste pelli non passeranno inosservati, {name}.\n\nGrazie per la tua dedizione.", 0x1bed65d5, 0x27d84e49, 0x3e2a3766, 0x0dcdb776, 0x715ed582, "....." },
  [1487] = { "Sradicamento dei deviati", "Ebru, nelle Wailing Caverns, vuole che tu uccida 7 Deviate Ravager, 7 Deviate Viper, 7 Deviate Shambler e 7 Deviate Dreadfang.", "Naralex aveva un obiettivo nobile.\n\nIl nostro grande capo aspirava a entrare nell'Emerald Dream e aiutare queste terre aspre a tornare la foresta rigogliosa di un tempo. Ma qualcosa è andato terribilmente storto.\n\nIl sogno di Naralex si è trasformato in un incubo e creature corrotte hanno cominciato ad abitare le caverne.\n\nMentre alcuni Disciples of Naralex cercano di risvegliare il nostro maestro, a me preme liberare queste grotte dalle bestie malvagie.\n\nSfida le caverne, {name}, e sradica la progenie deviata.", "{name}, noi, i Disciples of Naralex, abbiamo bisogno del tuo aiuto. Il nostro numero si assottiglia mentre il nostro maestro è intrappolato nel suo incubo distorto. Non abbiamo le forze necessarie per affrontare le creature corrotte che ora infestano queste caverne.\n\nTi supplico, entra nelle grotte e fa' guerra alle creature deviate!", "Come Disciple of Naralex, lodo il tuo coraggio, {name}.\n\nIl tuo aiuto nel ripulire le caverne è il primo passo nella nostra lunga lotta per vedere le Barrens risanate.\n\nGrazie, e che tu possa prosperare.", 0x97d1256c, 0x65cf05d4, 0xc616bee2, 0x56e545f4, 0x09635dc9, "....." },
  [1491] = { "Bevande intelligenti", "Porta 6 porzioni di Wailing Essence a Mebok Mizzyrix, a Ratchet.", "Va bene, le corna di raptor non hanno funzionato granché. Ma non importa: nessuno si è arricchito al primo tentativo! E poi credo di aver trovato qualcosa che funzionerà ancora meglio nelle mie bevande intelligenti!\n\nC'è una sostanza chiamata Wailing Essence, e credo che sia la causa delle strane piante e degli strani animali delle Barrens. Procuramene un po' e la proverò nella mia bevanda!\n\nHo sentito che l'essenza si accumula nelle creature ectoplasmatiche delle Wailing Caverns, a ovest. Dai la caccia a quelle creature e raccogli l'essenza.", "Dov'è la mia wailing essence?", "Ottimo, l'hai presa! Non vedo l'ora di provarla. Mi farà fare una fortuna, lo so!\n\nGrazie, {name}. Prendi questo, e quando sarò ricco te ne manderò ancora, promesso!", 0x3bd3c186, 0x92e0631f, 0x440930e0, 0x1ed90584, 0x985f6f88, "....." },
  [1504] = { "Il vincolo", nil, nil, nil, nil, 0x5926988f, nil, nil, nil, nil, ".mmmm" },
  [1507] = { "Il divoratore di anime", nil, nil, nil, nil, 0xc90e9da6, nil, nil, nil, nil, ".mmmm" },
  [1513] = { "Il vincolo", nil, nil, nil, nil, 0x5926988f, nil, nil, nil, nil, ".mmmm" },
  [1528] = { "Il richiamo dell'acqua", "Trova Islen Waterseer nelle Barrens.", nil, nil, "Il vento ti raggiunge rapido dall'orizzonte; la terra è salda sotto i tuoi piedi; e il tuo spirito è già scaldato dal fuoco. Direi che è tempo che tu impari la purezza dell'acqua.\n\nIl tuo cammino ti ha portato fin qui, e il tuo spirito ti darà la forza di proseguire ancora oltre. Ma il primo passo spetta a te.", 0x1f0e11aa, 0x52f30fbd, nil, nil, 0xf9228c66, "..mm." },
  [1529] = { "Il richiamo dell'acqua", "Trova Islen Waterseer nelle Barrens.", nil, nil, "Il vento ti raggiunge rapido dall'orizzonte; la terra è salda sotto i tuoi piedi; e il tuo spirito è già scaldato dal fuoco. Direi che è tempo che tu impari la purezza dell'acqua.\n\nIl tuo cammino ti ha portato fin qui, e il tuo spirito ti darà la forza di proseguire ancora oltre. Ma il primo passo spetta a te.", 0x1f0e11aa, 0x52f30fbd, nil, nil, 0xf9228c66, "..mm." },
  [1530] = { "Il richiamo dell'acqua", "Trova Brine nelle Southern Barrens.", "Se c'è una lezione che devi imparare sull'acqua, è questa: l'acqua significa rinascita.\n\nIl suo potere scorre, erode e purifica ogni genere di cosa. Troverai la sua capacità di guarire e rigenerare impareggiabile, ma solo quando è pura.\n\nQuando capirai che l'acqua, se inquinata, può devastare tutto ciò che tocca, comprenderai quanto sia una risorsa vitale.\n\nSe desideri la water sapta, trova Brine nel profondo delle Southern Barrens. La sua casa è continuamente molestata dai quilboar di quella zona.", nil, "Sì?\n\nMmm. Ho la sensazione di sapere cosa stai per chiedermi: cosa spinge qualcuno a vivere qui, nella parte più remota delle Barrens, con la minaccia dei quilboar tutt'intorno e senza protezione? Beh, abbiamo tutti le nostre ragioni per giustificare come agiamo. La vera domanda è: cosa porta un umile membro della razza {race} negli angoli più remoti delle Barrens a parlare con una donna che evidentemente non si preoccupa del proprio benessere?\n\nScommetto che entrambi conosciamo la risposta.", 0x1f0e11aa, 0xee4ba4c3, 0xfd15e1c1, nil, 0xfab4a730, "...m." },
  [1534] = { "Il richiamo dell'acqua", nil, nil, nil, nil, 0x1f0e11aa, nil, nil, nil, nil, ".mmmm" },
  [1535] = { "Il richiamo dell'acqua", nil, nil, nil, nil, 0x1f0e11aa, nil, nil, nil, nil, ".mmmm" },
  [1536] = { "Il richiamo dell'acqua", nil, nil, nil, nil, 0x1f0e11aa, nil, nil, nil, nil, ".mmmm" },
  [1579] = { nil, "Porta 8 Gaffer Jacks a Wizbang Cranktoggle, ad Auberdine.", "Sono venuto ad Auberdine per la tranquillità. Voglio inventare le mie invenzioni dove c'è silenzio, perché dopo una notte di bevute non sopporto tutto il chiasso di Ironforge!\n\nCosì ho preso una nave per Auberdine e durante il viaggio ho bevuto un po' troppo. Ho fatto cadere in mare la mia scatola di Gaffer Jacks! Mi servono i miei Gaffer Jacks!\n\nNon so di preciso dove li ho fatti cadere, ma se li peschi nell'oceano potresti avere fortuna...", "Hai trovato i miei gaffer jack, {name}? Senza i miei gaffer jack non posso accordare i miei stintle peg!", "Non posso credere che tu li abbia trovati! Devi essere il membro più fortunato della razza {race} in tutto Kalimdor!", nil, 0xb6cf36d8, 0xf09fa27e, 0x68a8175d, 0x9be37eba, "m...." },
  [1580] = { nil, "Porta 12 Electropellers a Wizbang Cranktoggle, ad Auberdine.", "Sappiamo che hai fortuna, ma... quanta fortuna hai, {name}?\n\nUna notte vagavo per le strade di Darkshore. Cercavo un bel fiume o un lago dove provare la mia nuova anatra da richiamo esplosiva semovente, e credo di essere stato un po' alticcio... perché sono svenuto e mi sono svegliato ore dopo ad Auberdine. Avevo i capelli bruciacchiati e la mia sacca di Electropellers era sparita! Devo averli fatti cadere in acqua!\n\nMi servono quegli Electropellers! Forse puoi ripescarli in qualche lago o torrente di Darkshore...", "Hai trovato qualche electropeller? Mi servono, se devo continuare le mie ricerche sulle anatre da richiamo...", "Non ci credo! Li hai trovati! Sei il miglior pescatore che abbia mai visto!\n\nGrazie, {name}. E tieni, prendi questi. Anche se sei così <bravo/brava> che probabilmente non ti servono, ti aiuteranno a pescare.", nil, 0xdc46859a, 0x642310a5, 0xf9546f58, 0xc63f8173, "m...." },
  [1581] = { "Elisir per i Bladeleafs", "Porta 6 Elixirs of Lion's Strength e 2 Elixirs of Minor Defense a Syral Bladeleaf, a Dolanaar.", "La nostra bottega di erbe e alchimia va a gonfie vele, ma mio marito passa così tanto tempo a preparare pozioni che non abbiamo mai tempo per noi.\n\nPuoi aiutarci?\n\nSe mi porti una scorta di elisir già pronti, sarò felice di fare uno scambio con te. Ho delle erbe rare che potrebbero tornarti utili.", "Salve, {name}. Hai gli elisir da scambiare?", "Sono ben miscelati. Metti grande cura nel tuo mestiere, {name}, ed è importante per un alchimista.\n\nEcco le tue erbe, appena raccolte. Usale bene.", 0x55e6a1a0, 0x4cd053d4, 0x114405e0, 0x486738da, 0xd85fcf4b, "....." },
  [1582] = { nil, "Porta 1 Embossed Leather Glove, 5 Embossed Leather Boots e 5 Embossed Leather Cloaks a Lotherias, a Darnassus.", "Noi di Darnassus, soprattutto noi artigiani, siamo molto impegnati. I giovani avventurieri non vedono l'ora di mettersi alla prova nelle terre selvagge, e hanno continuamente bisogno di provviste.\n\nSe mi aiuti a evadere i miei ordini di articoli di cuoio, forse potrò insegnarti una tecnica avanzata di conciatura.", "Salute, {name}.", "Sì, sono pezzi buoni. Hai una mano abile e occhio per i dettagli. Il tuo futuro da conciatore è promettente.\n\nEcco, {name}. Lascia che ti mostri il modello per fare il Moonglow Vest.", nil, 0xd2ae52ab, 0x86455e3c, 0x1355ea4c, 0x60bb3c3a, "m...." },
  [1598] = { "Il tomo rubato", "Recupera i Powers of the Void per Drusilla La Salle.", "Ehi, tu! {name}, giusto?\n\nSpero che tu sia <convinto/convinta> di voler diventare <uno/una> <stregone/strega>, perché se non sai cavartela da <solo/sola>, finirai per farti trascinare a fondo.\n\nDevo istruirti, ma prima devo assicurarmi che tu sia abbastanza forte.\n\nC'era un novizio che studiava all'abbazia ed è scappato per unirsi alla Defias Brotherhood. Perché mi interessa? Be', ha rubato alcuni libri importanti.\n\nUno di questi è proprio un libro che volevo per me, i Powers of the Void. Rubalo per me: lo tengono nascosto nella loro tenda nei vigneti.", "Rubare il libro di persona avrebbe dato troppo nell'occhio. Che fortuna che uno dei loro tirapiedi abbia fatto il lavoro sporco per me.", "Eccellente... Non sono mai riuscita a mettere le mani su questo testo: era custodito in un'ala protetta della biblioteca, e aggirarmi da quelle parti sarebbe sembrato sospetto.\n\nBe', hai fatto un buon lavoro a procurartelo, e sono convinta che tu sia in grado di gestire un imp tutto tuo, quindi non c'è motivo per non mostrarti come evocarne uno.", 0x88b1dee6, 0x8e23bc14, 0x4748064a, 0xdb594d3a, 0x048d8e41, "....." },
  [1599] = { "Inizi", "Porta 3 Feather Charms ad Alamar Grimm, ad Anvilmar.", "Devi essere <il/la> <nuovo/nuova> <stregone/strega> di cui tutti bisbigliano. Qualcuno deve averti preso in simpatia, se mi hanno chiesto di sottrarre tempo alle mie ricerche per cominciare il tuo addestramento.\n\nNon preoccuparti, non te ne farò una colpa.\n\nIl più semplice degli incantesimi di evocazione che imparerai è quello dell'imp. Prima di insegnartelo, però, devi dimostrare di avere le capacità magiche e fisiche necessarie.\n\nPortami tre feather charms dai novizi Frostmane della grotta a sud-ovest.", "Quei feather charms che portano i novizi hanno una sorta di potere magico. Sarà interessante studiarli. Non me lo sarei aspettato dai troll.", "Molto bene, molto bene! Te la sei cavata bene, {name}. Forse l'interesse che ti stanno dimostrando è meritato, dopotutto.\n\nSarà compito degli altri deciderlo, ammesso che il tuo imp non ti sopraffaccia e stronchi la tua carriera sul nascere. Per ora mi basta sapere che probabilmente sopravvivrai ai tuoi primi mesi come {class}.\n\nUna parola sull'imp, {name}. Come sa chi è della razza {race}, non lasciarti ingannare dalle dimensioni: la sua magia può essere molto pericolosa.", 0xf98072ec, 0xf994bd58, 0xa842c92b, 0xeeb2dc13, 0xe52d5af0, "....." },
  [1638] = { "L'addestramento di un guerriero", "Parla con Harry Burlguard.", "Hai dimostrato di essere <un/una> <guerriero/guerriera> capace, {name}. Ma sei ancora giovane e hai molto da imparare.\n\nParla con Harry Burlguard: di solito è alla taverna Pig and Whistle, nella Old Town di Stormwind. Harry è un vecchio veterano e un buon maestro. Può insegnarti qualche mossa che ti terrà in vita più a lungo.", nil, "Oh oh! Bevi qualcosa con me, {name}. Fuori sembri una persona tosta, ma vediamo se il tuo stomaco regge qualche boccale del più forte del Pig and Whistle!!\n\nOppure... eri qui per una lezione?", 0x93c881d5, 0x0aef52fa, 0x0ff82d16, nil, 0x11af52b0, "...m." },
  [1639] = { "Bartleby l'ubriaco", "Parla con Bartleby.", "Sì, posso insegnarti. Ma prima voglio vedere che mosse conosci già.\n\nVedi quell'ubriaco laggiù in fondo al bancone? Bartleby? Voglio che tu prenda il suo boccale.\n\nAh, e se conosci Bartleby, sai che non te lo darà di sua spontanea volontà.", nil, "Salve, <bel/bella> <ragazzo/ragazza>! Che ci fa un tipino schizzinoso come te al Pig and Whistle? Occhio, o potresti romperti un'unghia...", 0x1785381a, 0x423c9e83, 0x1cf66148, nil, 0x99442b95, "...m.", nil, nil, nil, nil, 0x4102c003 },
  [1640] = { "Batti Bartleby", "Batti Bartleby, poi parlagli.", "Vuoi cosa?? Sei <matto/matta>!\n\nL'unico modo in cui avrai questo boccale è strapparmelo dalle mie fredde dita morte...", "L'unico modo in cui avrai questo boccale è strapparmelo dalle mie fredde dita morte...", "Sei molto più <tosto/tosta> di quanto sembri!", 0x26ecfd0d, 0x3f5bb9b0, 0xe0771850, 0xa0dfd961, 0xdc83d2d5, "....." },
  [1641] = { "Il Tome of Divinity", nil, nil, nil, nil, 0xe91f21c0, nil, nil, nil, nil, ".mmmm" },
  [1642] = { "Il Tome of Divinity", "Parla con Duthorian Rall, a Stormwind.", nil, nil, nil, 0xe91f21c0, 0x0f3ca705, nil, nil, nil, "..mmm" },
